		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 41 then\n    cfg = {\n        version = 41,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- Mana: arrow to my Wave Cannon Kyrios spot after Pantokrator.\n            kyrArrow = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Line colour for the \"Tether\" style (the user, 2026-11-15; it used to come out white).\n            tetherColor = \"Red\",\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Tether line colours (ABGR). Every colour slot of the line drawer gets the same one: with a white outline slot the\n    -- line came out white.\n    cfg.TETHER_COLOR_NAMES = { \"Red\", \"Orange\", \"Yellow\", \"Green\", \"Cyan\", \"Blue\", \"Magenta\", \"White\" }\n    cfg.TETHER_COLORS = { Red = 0xFF0000FF, Orange = 0xFF0088FF, Yellow = 0xFF00FFFF, Green = 0xFF00FF00, Cyan = 0xFFFFFF00,\n                          Blue = 0xFFFF0000, Magenta = 0xFFFF00FF, White = 0xFFFFFFFF }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                local colors = live.TETHER_COLORS or {}\n                local color = colors[live.values.tetherColor] or 0xFF0000FF\n                live.tetherDrawers = live.tetherDrawers or {}\n                local drawer = live.tetherDrawers[color]\n                if drawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    drawer = TensorCore.getCachedDrawer(color, color, color, color, 2, 0, overlay)\n                    live.tetherDrawers[color] = drawer\n                end\n                drawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() and not (Roster.state and Roster.state()) then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        local naur = Roster.state and Roster.state()\n        if naur then\n            saved = { members = {}, jobs = {} }\n            for slot, row in pairs(naur.bySlot) do saved.members[row.key] = slot; saved.jobs[row.key] = row.job end\n        end\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P1 Program Loop, Sui/Mitama/Yabba guide: towers 1-2-3-4, tethers 3-4-1-2.\n-- G2 searches North clockwise and G1 West counter-clockwise for towers, tethers and empty cardinals.\n-- Publishes my spot (s.spot), my next spot (s.nextSpot) and queues callouts (s.queue).\nlocal t = TensorReactions_CurrentTimer\nlocal s = data.topLooper\n-- A new pull: the timer drops a lot or frames stopped. Timeline syncs can step back a second or more mid-mechanic.\nif s == nil or (s.lastTime and (t < s.lastTime - 5 or Now() - (s.lastClock or Now()) > 5000)) then\n    s = {}\n    data.topLooper = s\nend\ns.lastTime = t\ns.lastClock = Now()\n\n-- OnFrame runs far more often than this needs; up to ten passes a second keep the spot fresh.\nlocal clock = Now()\nif s.nextPass and clock < s.nextPass then\n    self.used = true\n    return\nend\ns.nextPass = clock + 100\n\nif not s.initialized then\n    s.initialized = true\n    s.towerList = s.towerList or {}\n    s.resolved = 0\n    s.plans = {}\n    s.queue = {}\n    s.warned = {}\n    s.called = {}\n    s.idle = {}\n    s.lastHolders = \"\"\n    s.LINE_BUFFS = { [3004] = 1, [3005] = 2, [3006] = 3, [3451] = 4 }\n    s.TETHER_TYPE = 89\n    -- The guide's flex priority H1<R1<M1<T1 / T2>M2>R2>H2, highest first.\n    s.FLEX_PRIO = \"T1 M1 R1 H1 T2 M2 R2 H2\"\n    s.CONGA = { \"H1\", \"R1\", \"M1\", \"T1\", \"T2\", \"M2\", \"R2\", \"H2\" }\n    s.TETHER_LINE = { 3, 4, 1, 2 }\n    s.RESOLVE_AT = { 29.1, 38.1, 47.1, 56.1 }\n    s.BEARING = { N = 0, E = 90, S = 180, W = 270 }\n    s.ORDER = { g2 = { \"N\", \"E\", \"S\", \"W\" }, g1 = { \"W\", \"S\", \"E\", \"N\" } }\n    s.CARD_NAME = { N = \"north\", E = \"east\", S = \"south\", W = \"west\" }\n    s.GROUP_CALL = { g1 = \"G1 West counter clockwise\", g2 = \"G2 North clockwise\" }\n    -- Elemental priority, clockwise from NW (roles mapped: MT=T1, ST=T2, D1=M1, D2=M2, D3=R1, D4=R2).\n    s.ELEMENTAL_PRIO = { \"H1\", \"T1\", \"T2\", \"M1\", \"M2\", \"R1\", \"R2\", \"H2\" }\n    s.ELEMENTAL_CALL = { g2 = \"First of your number, clockwise from northwest\", g1 = \"Second of your number\" }\n    -- LPDU (raidplan 7gDX3dkkPX1kO9u2, \"MTRH Prio for everything\"): M1>M2>MT>OT>R1>R2>H1>H2. The higher of a number soaks the\n    -- first tower, grabs the first tether and soaks it at the first free cardinal clockwise from N; the other takes the first\n    -- counter-clockwise. That's G2's and G1's searches again.\n    s.LDPU_PRIO = { \"M1\", \"M2\", \"T1\", \"T2\", \"R1\", \"R2\", \"H1\", \"H2\" }\n    s.LDPU_CALL = { g2 = \"Higher of your number: clockwise from north\", g1 = \"Lower of your number: counter-clockwise\" }\n    -- Slide 13: the Party stack, and the 3's in front of it.\n    s.STACK = { x = 100, z = 115 }\n    s.FRONT = { g1 = { x = 99, z = 109 }, g2 = { x = 101, z = 109 } }\n    s.IDLE_RADIUS = 12\n    s.IDLE_ARC = 35\n    s.TOWER_CLEARANCE = 4\n    s.drawMine = TensorCore.getCachedDrawer(nil, nil, 0x6600FF00, 0xFF00FF00, 2)\n    -- Red, so it's easy to find (the user, 2026-11-08): the next-spot ring and the small circle on my current spot.\n    s.drawNext = TensorCore.getCachedDrawer(nil, nil, 0x550000FF, 0xFF0000FF, 2)\n    s.drawSpot = TensorCore.getCachedDrawer(nil, nil, 0x660000FF, 0xFF0000FF, 2)\n    -- Same drawer as the standard guide arrow.\n    s.drawArrow = cfg.styledArrow(\"stLoop\", TensorCore.getCachedDrawer(0xFF00FFFF, 0xFF0088FF, 0xFF0000FF, 0xFFFFFFFF, 2))\n\n    function s.log(text)\n        d(\"[Looper] \" .. text)\n        TensorCore.timelineLogToFile(\"[Looper] \" .. text .. \"\\n\")\n    end\n\n    function s.warnOnce(key, text)\n        if not s.warned[key] then\n            s.warned[key] = true\n            s.log(text)\n        end\n    end\n\n    function s.say(key, text, prio, tts)\n        if not s.called[key] then\n            s.called[key] = true\n            s.queue[#s.queue + 1] = { text = text, prio = prio, tts = tts }\n        end\n    end\n\n    function s.dist(a, b)\n        local dx, dz = a.x - b.x, a.z - b.z\n        return math.sqrt(dx * dx + dz * dz)\n    end\n\n    function s.ring(bearing, radius)\n        local a = math.rad(bearing)\n        return { x = 100 + radius * math.sin(a), z = 100 - radius * math.cos(a) }\n    end\n\n    function s.bearingOf(x, z)\n        return math.deg(math.atan2(x - 100, 100 - z)) % 360\n    end\n\n    function s.cardinalOf(x, z)\n        local dx, dz = x - 100, z - 100\n        if math.abs(dz) >= math.abs(dx) then\n            return dz < 0 and \"N\" or \"S\"\n        end\n        return dx > 0 and \"E\" or \"W\"\n    end\n\n    function s.angleBetween(a, b)\n        local diff = math.abs(a - b) % 360\n        return diff > 180 and 360 - diff or diff\n    end\n\n    -- Blaster casts and the time fallback both land here, so a set can only resolve once.\n    function s.markResolved(now)\n        for set, at in ipairs(s.RESOLVE_AT) do\n            if math.abs(now - at) < 4 and set > s.resolved then\n                s.resolved = set\n            end\n        end\n    end\n\n    function s.roleOf(line, set)\n        if line == set then return \"tower\" end\n        if line == s.TETHER_LINE[set] then return \"tether\" end\n        return \"idle\"\n    end\n\n    -- Slides 15-18: as far from the towers as possible, in moderation. Turning away from the\n    -- closer tower is also the \"G1 cheats north, G2 cheats south\" of the opposite-tower sets.\n    function s.tetherSpot(card, a, b, values)\n        local bearing = s.BEARING[card]\n        local spot = s.ring(bearing, values.tetherRadius)\n        local toA, toB = s.dist(spot, a), s.dist(spot, b)\n        if math.abs(toA - toB) > 0.01 then\n            local closer = toA < toB and a or b\n            local plus = s.ring(bearing + values.tetherAngle, values.tetherRadius)\n            local minus = s.ring(bearing - values.tetherAngle, values.tetherRadius)\n            spot = s.dist(plus, closer) >= s.dist(minus, closer) and plus or minus\n        end\n        spot.card = card\n        return spot\n    end\n\n    function s.planSet(set, values)\n        if s.plans[set] then return s.plans[set] end\n        local a, b = s.towerList[set * 2 - 1], s.towerList[set * 2]\n        if b == nil then return nil end\n        local byCard = { [s.cardinalOf(a.x, a.z)] = a, [s.cardinalOf(b.x, b.z)] = b }\n        local plan = { a = a, b = b, cards = byCard }\n        for _, group in ipairs({ \"g1\", \"g2\" }) do\n            local towerCard, spotCard\n            for _, card in ipairs(s.ORDER[group]) do\n                if byCard[card] then\n                    towerCard = towerCard or card\n                else\n                    spotCard = spotCard or card\n                end\n            end\n            plan[group] = { towerCard = towerCard, tower = byCard[towerCard], spotCard = spotCard,\n                            tetherSpot = s.tetherSpot(spotCard, a, b, values) }\n        end\n        -- Slide 15: stand in the tower, cheating away from the tether players.\n        for _, group in ipairs({ \"g1\", \"g2\" }) do\n            local g = plan[group]\n            local one, two = plan.g1.tetherSpot, plan.g2.tetherSpot\n            local nearest = s.dist(g.tower, one) <= s.dist(g.tower, two) and one or two\n            local dx, dz = g.tower.x - nearest.x, g.tower.z - nearest.z\n            local len = math.max(0.01, math.sqrt(dx * dx + dz * dz))\n            g.soak = { x = g.tower.x + dx / len * values.towerOffset, z = g.tower.z + dz / len * values.towerOffset }\n        end\n        s.plans[set] = plan\n        s.log(string.format(\"set %d towers (%.0f,%.0f) (%.0f,%.0f) | G1 tower %s tether %s (%.1f,%.1f) | G2 tower %s tether %s (%.1f,%.1f)\",\n            set, a.x, a.z, b.x, b.z, plan.g1.towerCard, plan.g1.spotCard, plan.g1.tetherSpot.x, plan.g1.tetherSpot.z,\n            plan.g2.towerCard, plan.g2.spotCard, plan.g2.tetherSpot.x, plan.g2.tetherSpot.z))\n        return plan\n    end\n\n    -- Slides 14, 18, 24: as far from the tether players as possible, on the same cardinal as a tower.\n    function s.idleSpot(plan, me, mine, set)\n        local cleansed = mine.line < set\n        local cardA, cardB = s.cardinalOf(plan.a.x, plan.a.z), s.cardinalOf(plan.b.x, plan.b.z)\n        local myBearing = s.bearingOf(me.pos.x, me.pos.z)\n        local toA, toB = s.angleBetween(myBearing, s.BEARING[cardA]), s.angleBetween(myBearing, s.BEARING[cardB])\n        local card = plan[mine.group].towerCard\n        if math.abs(toA - toB) >= 1 then\n            card = toA < toB and cardA or cardB\n        end\n        local one, two = plan.g1.tetherSpot, plan.g2.tetherSpot\n        local best, bestScore, bestOffset\n        for offset = -s.IDLE_ARC, s.IDLE_ARC, 5 do\n            local spot = s.ring(s.BEARING[card] + offset, s.IDLE_RADIUS)\n            if cleansed or (s.dist(spot, plan.a) >= s.TOWER_CLEARANCE and s.dist(spot, plan.b) >= s.TOWER_CLEARANCE) then\n                local score = math.min(s.dist(spot, one), s.dist(spot, two))\n                if best == nil or score > bestScore + 0.001\n                    or (math.abs(score - bestScore) <= 0.001 and math.abs(offset) < bestOffset) then\n                    best, bestScore, bestOffset = spot, score, math.abs(offset)\n                end\n            end\n        end\n        best.kind, best.card = \"idle\", card\n        return best\n    end\n\n    -- A holder stays a holder for 0.5s after its tether blinks out (2026-11-23), so a handoff doesn't flicker the arrows.\n    function s.readTethers()\n        local holders, bossID, seen = {}, nil, {}\n        local now = Now()\n        s.heldAt = s.heldAt or {}\n        for source, list in pairs(Argus.getCurrentTethers()) do\n            for _, tether in ipairs(list) do\n                if tether.type == s.TETHER_TYPE then\n                    holders[#holders + 1] = source\n                    seen[source] = true\n                    s.heldAt[source] = now\n                    bossID = tether.targetid\n                end\n            end\n        end\n        for id, at in pairs(s.heldAt) do\n            if not seen[id] then\n                if now - at <= 500 then holders[#holders + 1] = id else s.heldAt[id] = nil end\n            end\n        end\n        return holders, bossID\n    end\n\n    -- The tether I go for: one still held by someone who isn't this set's tether player.\n    -- With two open, G2 takes the first going North clockwise. On cardinals, the first going\n    -- West counter-clockwise is always the other one, so G1 takes that.\n    function s.tetherToTake(set, group, holders)\n        local open = {}\n        for _, id in ipairs(holders) do\n            local holder = TensorCore.mGetEntity(id)\n            local rec = s.byId[id]\n            if holder and holder.pos and (rec == nil or rec.line ~= s.TETHER_LINE[set]) then\n                local rank = 0\n                local card = s.cardinalOf(holder.pos.x, holder.pos.z)\n                for i, c in ipairs(s.ORDER.g2) do\n                    if c == card then rank = i end\n                end\n                open[#open + 1] = { id = id, rank = rank, bearing = s.bearingOf(holder.pos.x, holder.pos.z) }\n            end\n        end\n        if #open == 0 then return nil end\n        if #open == 1 then return open[1].id end\n        local first, second = open[1], open[2]\n        if second.rank < first.rank or (second.rank == first.rank and second.bearing < first.bearing) then\n            first, second = second, first\n        end\n        return group == \"g2\" and first.id or second.id\n    end\n\n    -- Slide 17: grab the tether decently far under the boss.\n    function s.grabPoint(tetherID, values)\n        local holder, boss = TensorCore.mGetEntity(tetherID), TensorCore.mGetEntity(s.bossID)\n        if holder == nil or holder.pos == nil or boss == nil or boss.pos == nil then return nil end\n        local dx, dz = holder.pos.x - boss.pos.x, holder.pos.z - boss.pos.z\n        local len = math.sqrt(dx * dx + dz * dz)\n        if len < 0.1 then return { x = boss.pos.x, z = boss.pos.z } end\n        local reach = math.min(len, values.grabDistance)\n        return { x = boss.pos.x + dx / len * reach, z = boss.pos.z + dz / len * reach }\n    end\n\n    -- Roster link: read the in-line debuffs, let resolveFlex decide who moves, publish per player.\n    function s.solve(Roster, me)\n        local view = cfg.rosterView(Roster, me)\n        if view == nil then\n            s.warnOnce(\"view\", \"Party Roster not ready and its jobs don't match the players here\")\n            return\n        end\n        if not view.ready then s.warnOnce(\"jobs\", \"Party Roster not ready: matching players by job\") end\n        s.view = view\n        local g1, g2 = view.groups(\"g1\"), view.groups(\"g2\")\n        local inLine, counts = {}, { 0, 0, 0, 0 }\n        for _, list in ipairs({ g1, g2 }) do\n            for _, id in ipairs(list) do\n                for buff, line in pairs(s.LINE_BUFFS) do\n                    if TensorCore.hasBuff(id, buff) then\n                        inLine[id] = line\n                        counts[line] = counts[line] + 1\n                    end\n                end\n            end\n        end\n        if counts[1] ~= 2 or counts[2] ~= 2 or counts[3] ~= 2 or counts[4] ~= 2 then return end\n        -- Mana (lodestone blog 5536808): \"CW from NW > H1 MT ST D1 D2 D3 D4 H2\", the same line as Elemental.\n        local elementalLine = cfg.values.elemental or cfg.values.mana\n        if elementalLine or cfg.values.ldpu then\n            local prioList = elementalLine and s.ELEMENTAL_PRIO or s.LDPU_PRIO\n            -- Elemental (ffxiv.tuufless.com/elemental/top/01_omega): towers and tether spots go clockwise from NW in priority\n            -- H1 MT ST D1 D2 D3 D4 H2. The higher of the two players with a number takes the first one clockwise from NW, which\n            -- is exactly what G2's North-clockwise search picks, so they go in G2 and the other in G1. No flex.\n            local rank = {}\n            for i, slot in ipairs(prioList) do\n                local id = view.idOf(slot)\n                if id then rank[id] = i end\n            end\n            local byLine = {}\n            for id, line in pairs(inLine) do\n                byLine[line] = byLine[line] or {}\n                table.insert(byLine[line], id)\n            end\n            local byId = {}\n            for line, ids in pairs(byLine) do\n                table.sort(ids, function(a, b) return (rank[a] or 99) < (rank[b] or 99) end)\n                byId[ids[1]] = { group = \"g2\", line = line, flexed = false }\n                if ids[2] then byId[ids[2]] = { group = \"g1\", line = line, flexed = false } end\n            end\n            s.byId = byId\n            s.mine = view.publish(\"topLooper\", byId)\n            s.mySlot = view.mySlot()\n            s.solved = true\n            s.ranked = elementalLine and s.ELEMENTAL_CALL or s.LDPU_CALL\n            local lineText = {}\n            for _, slot in ipairs(prioList) do\n                local id = view.idOf(slot)\n                lineText[#lineText + 1] = slot .. \"=\" .. tostring(inLine[id]) .. (byId[id] and (byId[id].group == \"g2\" and \"a\" or \"b\") or \"\")\n            end\n            s.log((cfg.values.elemental and \"Elemental\" or cfg.values.mana and \"Mana\" or \"LPDU\") .. \" in line \" .. table.concat(lineText, \" \"))\n            return\n        end\n        local groups, swaps = view.resolveFlex({\n            groups = { g1 = g1, g2 = g2 },\n            attrOf = inLine,\n            prio = s.FLEX_PRIO,\n            polarity = \"higherMoves\",\n        })\n        if groups == nil then\n            s.warnOnce(\"flex\", \"resolveFlex returned no groups\")\n            return\n        end\n        local byId = {}\n        for _, group in ipairs({ \"g1\", \"g2\" }) do\n            for _, id in ipairs(groups[group]) do\n                byId[id] = { group = group, line = inLine[id], flexed = false }\n            end\n        end\n        local swapText = {}\n        for _, swap in ipairs(swaps or {}) do\n            byId[swap.a].flexed = true\n            byId[swap.b].flexed = true\n            swapText[#swapText + 1] = tostring(view.slotOf(swap.a)) .. \"<->\" .. tostring(view.slotOf(swap.b))\n        end\n        s.byId = byId\n        s.mine = view.publish(\"topLooper\", byId)\n        s.mySlot = view.mySlot()\n        s.solved = true\n        local lineText = {}\n        for _, slot in ipairs(s.CONGA) do\n            lineText[#lineText + 1] = slot .. \"=\" .. tostring(inLine[view.idOf(slot)])\n        end\n        s.log(\"in line \" .. table.concat(lineText, \" \") .. \" | flex \" .. (#swapText > 0 and table.concat(swapText, \" \") or \"none\"))\n    end\nend\n\nlocal Roster = NAUR_Roster or (AnyoneCore and AnyoneCore.Roster)\nif Roster == nil or Roster.current() == nil then\n    s.warnOnce(\"roster\", \"Party Roster not set\")\n    s.say(\"roster\", \"Set the Party Roster\", 3, false)\n    self.used = true\n    return\nend\nlocal me = TensorCore.mGetPlayer()\nif not s.solved and me and me.pos then\n    s.solve(Roster, me)\nend\nlocal mine = s.mine\nif not s.solved or mine == nil or me == nil or me.pos == nil then\n    self.used = true\n    return\nend\nlocal values = cfg.values\ns.say(\"group\", (mine.flexed and \"FLEX \" or \"\") .. (s.ranked or s.GROUP_CALL)[mine.group], mine.flexed and 3 or 1, true)\n\n-- A missed Blaster cast must not stall the sets.\nlocal pending = s.resolved + 1\nif pending <= 4 and t > s.RESOLVE_AT[pending] + 2 then\n    s.resolved = pending\nend\nlocal set = s.resolved + 1\ns.set = set\nif set > 4 then\n    s.spot, s.nextSpot = nil, nil\n    self.used = true\n    return\nend\n\nlocal holders, bossID = s.readTethers()\nif bossID then s.bossID = bossID end\nlocal iHold = false\nlocal holderText = {}\nfor _, id in ipairs(holders) do\n    if id == me.id then iHold = true end\n    holderText[#holderText + 1] = tostring(s.view.slotOf(id))\nend\ntable.sort(holderText)\nholderText = table.concat(holderText, \" \")\nif holderText ~= s.lastHolders then\n    s.lastHolders = holderText\n    s.log(string.format(\"set %d tethers on: %s\", set, holderText))\nend\n\n-- Slide 14: non 3's wait until both 3's have their tethers.\nif set == 1 and not s.released then\n    local threes = 0\n    for _, id in ipairs(holders) do\n        local rec = s.byId[id]\n        if rec and rec.line == s.TETHER_LINE[1] then threes = threes + 1 end\n    end\n    if #holders > 0 and s.tetherTime == nil then s.tetherTime = t end\n    s.released = threes >= 2 or (s.tetherTime ~= nil and t >= s.tetherTime + 3)\nend\n\nlocal plan = s.planSet(set, values)\nlocal g = plan and plan[mine.group]\nlocal role = s.roleOf(mine.line, set)\nlocal spot\nif role == \"tether\" then\n    if iHold then\n        if g then\n            spot = { x = g.tetherSpot.x, z = g.tetherSpot.z, kind = \"tether\", card = g.spotCard }\n        end\n    else\n        local tetherID = s.tetherToTake(set, mine.group, holders)\n        local point = tetherID and s.grabPoint(tetherID, values)\n        if point then\n            spot = { x = point.x, z = point.z, kind = \"grab\", tetherID = tetherID }\n        elseif set == 1 then\n            spot = { x = s.FRONT[mine.group].x, z = s.FRONT[mine.group].z, kind = \"front\" }\n        end\n    end\nelseif set == 1 and not s.released then\n    spot = { x = s.STACK.x, z = s.STACK.z, kind = \"wait\" }\nelseif g then\n    if role == \"tower\" then\n        spot = { x = g.soak.x, z = g.soak.z, kind = \"tower\", card = g.towerCard, tower = g.tower }\n    elseif iHold then\n        -- Slide 17: the last holder stays put until the tether is taken.\n        spot = { x = me.pos.x, z = me.pos.z, kind = \"hold\" }\n    else\n        s.idle[set] = s.idle[set] or s.idleSpot(plan, me, mine, set)\n        spot = s.idle[set]\n    end\nend\ns.spot = spot\n\n-- Slide 16: the next towers appear just before this set ends, so show where I go next.\nlocal nextSpot\nlocal nextPlan = set < 4 and s.planSet(set + 1, values)\nif nextPlan then\n    local nextRole = s.roleOf(mine.line, set + 1)\n    local nextG = nextPlan[mine.group]\n    if nextRole == \"tower\" then\n        nextSpot = { x = nextG.soak.x, z = nextG.soak.z, tower = nextG.tower }\n    elseif nextRole == \"tether\" then\n        nextSpot = { x = nextG.tetherSpot.x, z = nextG.tetherSpot.z }\n    end\nend\ns.nextSpot = nextSpot\n\n-- Call my job in a set as soon as its towers appear.\nfor callSet = set, math.min(set + 1, 4) do\n    local callPlan = s.planSet(callSet, values)\n    if callPlan then\n        local callRole = s.roleOf(mine.line, callSet)\n        local callG = callPlan[mine.group]\n        if callRole == \"tower\" then\n            s.say(\"set\" .. callSet, \"Tower \" .. s.CARD_NAME[callG.towerCard], 2, true)\n        elseif callRole == \"tether\" then\n            s.say(\"set\" .. callSet, \"Tether to \" .. s.CARD_NAME[callG.spotCard], 3, true)\n        else\n            s.say(\"set\" .. callSet, \"Set \" .. callSet .. \" free\", 1, false)\n        end\n    end\nend\n\n-- Slides 20 and 22: tanks and healers restore the 3's and 4's before they soak.\nif values.topUp and set >= 3 and s.mySlot and (s.mySlot:sub(1, 1) == \"T\" or s.mySlot:sub(1, 1) == \"H\") then\n    s.say(\"topup\" .. set, set == 3 and \"Top up 3's to 35k\" or \"Top up 4's\", 2, false)\nend\n\nlocal spotKey = spot and (set .. spot.kind) or nil\nif spotKey ~= s.lastSpotKey and spot then\n    s.lastSpotKey = spotKey\n    s.log(string.format(\"set %d %s %s (%.1f,%.1f)\", set, tostring(s.mySlot), spot.kind, spot.x, spot.z))\nend\nself.used = true\n",
							name = "Solve Program Loop",
