					{
						data = 
						{
							aType = "Lua",
							actionLua = "local s = data.topLooper\nlocal cfg = data.topLooperSettings\nif s == nil or cfg == nil or s.drawMine == nil then\n    self.used = true\n    return\nend\nlocal me = TensorCore.mGetPlayer()\nif me == nil or me.pos == nil or me.hp.current <= 0 then\n    self.used = true\n    return\nend\nlocal values = cfg.values\nlocal y = me.pos.y\n\n-- Red: where I go next.\nlocal nextSpot = s.nextSpot\nif nextSpot and values.nextRing then\n    s.drawNext:addCircle(nextSpot.x, y, nextSpot.z, 0.8)\n    if nextSpot.tower then\n        s.drawNext:addDonut(nextSpot.tower.x, y, nextSpot.tower.z, 2.6, 3.2)\n    end\nend\n\n-- Where I go now: a red circle on the spot, the tower ring in green, and an arrow sized and drawn like the standard guide arrow.\nlocal spot = s.spot\nif spot then\n    (s.drawSpot or s.drawMine):addCircle(spot.x, y, spot.z, 0.8)\n    if spot.tower then\n        s.drawMine:addDonut(spot.tower.x, y, spot.tower.z, 2.6, 3.2)\n    end\n    if values.arrow then\n        local dx, dz = spot.x - me.pos.x, spot.z - me.pos.z\n        local dist = math.sqrt(dx * dx + dz * dz)\n        local scale = math.min(1, dist / 15)\n        local tipLength = math.max(2, 3 * scale)\n        local baseLength = dist - tipLength\n        if baseLength > 1 then\n            s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spot.x, y, spot.z),\n                baseLength, math.max(0.5, scale), tipLength, math.max(1.5, 3 * scale),\n                false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n        end\n    end\nend\nself.used = true\n",
