				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- NAUR Party Roster (shared by the TEA/UCOB/UWU NAUR settings windows and TOP; same block in each, newest version wins).\n-- v7 (2026-11-15): the window is \"Party Roster\" (everyone's roster, not NAUR's). Seating is by role everywhere (phys R1,\n-- caster R2), except TOP (map 1122) with the NA region, which seats the caster R1 and phys ranged R2. The Region combo\n-- shows in TOP only. Everything else is as v6.\n-- v8 (2026-11-23): in TOP the Region follows the Preset by itself (no combo), and R1/R2 follow its rule even in a saved roster.\n-- Seats by NAUR rules (Regen H1, Shield H2, melee M1/M2, phys R1, caster R2), editable, saved per party.\n-- Same API as Anyone's roster; falls back to Anyone's roster when off or without 8 members.\nif not NAUR_Roster or (NAUR_Roster.version or 0) < 8 then\n local old = NAUR_Roster\n local R = { version = 8, slots = { \"T1\", \"T2\", \"H1\", \"H2\", \"M1\", \"M2\", \"R1\", \"R2\" } }\n R.folder = GetLuaModsPath() .. [[TensorReactions\\Settings\\]]\n R.path = R.folder .. [[NAUR-Roster.lua]]\n local saved = FileExists(R.path) and FileLoad(R.path)\n if type(saved) ~= \"table\" then saved = {} end\n R.enabled = saved.enabled ~= false\n R.REGIONS = { \"NA\", \"Elemental\", \"OCE\", \"LPDU\", \"Mana\" }\n R.region = \"NA\"\n for _, name in ipairs(R.REGIONS) do if saved.region == name then R.region = name end end\n function R.inTop() return Player ~= nil and Player.localmapid == 1122 end\n R.records = type(saved.records) == \"table\" and saved.records or {}\n R.show = old and old.show or false\n R.openedMap = old and old.openedMap\n R.lastDraw = old and old.lastDraw\n function R.save()\n  if not FolderExists(R.folder) then FolderCreate(R.folder) end\n  FileSave(R.path, { enabled = R.enabled, records = R.records, region = R.region })\n end\n local function anyone() return AnyoneCore and AnyoneCore[\"Roster\"] end\n local TANK = { [1] = true, [3] = true, [19] = true, [21] = true, [32] = true, [37] = true }\n local HEALER = { [6] = true, [24] = true, [28] = true, [33] = true, [40] = true }\n local REGEN = { [6] = true, [24] = true, [33] = true }\n local MELEE = { [2] = true, [4] = true, [20] = true, [22] = true, [29] = true, [30] = true, [34] = true, [39] = true, [41] = true }\n local PHYS = { [5] = true, [23] = true, [31] = true, [38] = true }\n local function partyList()\n  local rows = {}\n  for k, e in pairs(TensorCore.getEntityGroupList(\"Party\") or {}) do\n   if e and e.id then\n    local key = e.guid and tostring(e.guid) or e.name\n    if key then rows[#rows + 1] = { order = tonumber(k) or e.id, id = e.id, guid = key, key = key, job = e.job, name = e.name or \"?\" } end\n   end\n  end\n  table.sort(rows, function(a, b) return a.order < b.order end)\n  return rows\n end\n function R.autofill(list)\n  local bySlot, used = {}, {}\n  local function put(slot, row) if row and not bySlot[slot] and not used[row] then bySlot[slot] = row; used[row] = true end end\n  local tanks, healers, melee, ranged = {}, {}, {}, {}\n  for _, row in ipairs(list) do\n   if TANK[row.job] then tanks[#tanks + 1] = row\n   elseif HEALER[row.job] then healers[#healers + 1] = row\n   elseif MELEE[row.job] then melee[#melee + 1] = row\n   elseif row.job then ranged[#ranged + 1] = row end\n  end\n  table.sort(healers, function(a, b)\n   local ra, rb = REGEN[a.job] and 0 or 1, REGEN[b.job] and 0 or 1\n   if ra ~= rb then return ra < rb end\n   return a.order < b.order\n  end)\n  table.sort(ranged, function(a, b)\n   local pa, pb = PHYS[a.job] and 0 or 1, PHYS[b.job] and 0 or 1\n   -- TOP with the NA region: the caster takes R1 and physical ranged R2. Everywhere else physical ranged takes R1.\n   if pa ~= pb then if R.inTop() and R.region == \"NA\" then return pa > pb end return pa < pb end\n   return a.order < b.order\n  end)\n  put(\"T1\", tanks[1]); put(\"T2\", tanks[2])\n  put(\"H1\", healers[1]); put(\"H2\", healers[2])\n  put(\"M1\", melee[1]); put(\"M2\", melee[2])\n  put(\"R1\", ranged[1]); put(\"R2\", ranged[2])\n  for _, slot in ipairs(R.slots) do\n   if not bySlot[slot] then\n    for _, row in ipairs(list) do if not used[row] then put(slot, row) break end end\n   end\n  end\n  return bySlot\n end\n function R.build()\n  if R.inTop() and R.presetOf then local p = R.presetOf() if p and p ~= R.region then R.region = p end end\n  local list = partyList()\n  if #list ~= 8 then return nil end\n  local keys = {}\n  for i, row in ipairs(list) do keys[i] = row.key end\n  table.sort(keys)\n  local party = table.concat(keys, \",\")\n  local rec, bySlot = R.records[party], nil\n  if type(rec) == \"table\" then\n   bySlot = {}\n   local taken = {}\n   for _, slot in ipairs(R.slots) do\n    for _, row in ipairs(list) do\n     if row.key == rec[slot] and not taken[row] then bySlot[slot] = row; taken[row] = true end\n    end\n    if not bySlot[slot] then bySlot = nil break end\n   end\n   if not bySlot then rec = nil end\n  else\n   rec = nil\n  end\n  bySlot = bySlot or R.autofill(list)\n  if R.inTop() and bySlot.R1 and bySlot.R2 then\n   local p1, p2 = PHYS[bySlot.R1.job] and true or false, PHYS[bySlot.R2.job] and true or false\n   if p1 ~= p2 and p1 ~= (R.region ~= \"NA\") then bySlot.R1, bySlot.R2 = bySlot.R2, bySlot.R1 end\n  end\n  local s = { party = party, list = list, bySlot = bySlot, byId = {}, byKey = {}, saved = rec ~= nil, members = {} }\n  for _, slot in ipairs(R.slots) do\n   local row = bySlot[slot]\n   if not row then return nil end\n   row.slot = slot\n   s.byId[row.id] = row\n   s.byKey[row.key] = row\n   s.members[slot] = { guid = row.guid, job = row.job, name = row.name, id = row.id }\n  end\n  return s\n end\n function R.state()\n  if not R.enabled then return nil end\n  local now = os.clock()\n  if not R.cache or now - R.cache.t > 0.5 or now < R.cache.t then R.cache = { t = now, s = R.build() } end\n  return R.cache.s\n end\n function R.current() local s = R.state() if s then return s end local a = anyone() return a and a.current() end\n function R.members() local s = R.state() if s then return s.members end local a = anyone() return a and a.members() end\n function R.idOf(slot)\n  local s = R.state()\n  if s then local row = s.bySlot[slot] return row and row.id end\n  local a = anyone() return a and a.idOf(slot)\n end\n function R.entOf(slot)\n  local s = R.state()\n  if s then\n   local row = s.bySlot[slot]\n   if not row then return nil end\n   local me = TensorCore.mGetPlayer()\n   if me and me.id == row.id then return me end\n   return TensorCore.mGetEntity(row.id)\n  end\n  local a = anyone() return a and a.entOf(slot)\n end\n function R.slotOf(x)\n  local s = R.state()\n  if s then\n   local row = (type(x) == \"number\" and s.byId[x]) or s.byKey[tostring(x)]\n   return row and row.slot\n  end\n  local a = anyone() return a and a.slotOf(x)\n end\n function R.mySlot()\n  local s = R.state()\n  if s then\n   local me = TensorCore.mGetPlayer()\n   local row = me and s.byId[me.id]\n   return row and row.slot\n  end\n  local a = anyone() return a and a.mySlot()\n end\n function R.isReady()\n  local s = R.state()\n  if s then\n   for _, slot in ipairs(R.slots) do if not R.entOf(slot) then return false end end\n   return true\n  end\n  local a = anyone() return a and a.isReady()\n end\n local function recordOf(s)\n  local rec = {}\n  for _, slot in ipairs(R.slots) do rec[slot] = s.bySlot[slot].key end\n  return rec\n end\n local JOBNAME = { [1] = \"Gladiator\", [2] = \"Pugilist\", [3] = \"Marauder\", [4] = \"Lancer\", [5] = \"Archer\", [6] = \"Conjurer\",\n  [7] = \"Thaumaturge\", [19] = \"Paladin\", [20] = \"Monk\", [21] = \"Warrior\", [22] = \"Dragoon\", [23] = \"Bard\", [24] = \"WhiteMage\",\n  [25] = \"BlackMage\", [26] = \"Arcanist\", [27] = \"Summoner\", [28] = \"Scholar\", [29] = \"Rogue\", [30] = \"Ninja\", [31] = \"Machinist\",\n  [32] = \"DarkKnight\", [33] = \"Astrologian\", [34] = \"Samurai\", [35] = \"RedMage\", [36] = \"BlueMage\", [37] = \"Gunbreaker\",\n  [38] = \"Dancer\", [39] = \"Reaper\", [40] = \"Sage\", [41] = \"Viper\", [42] = \"Pictomancer\" }\n local LABEL = { T1 = \"MT\", T2 = \"OT\", H1 = \"H1\", H2 = \"H2\", M1 = \"M1\", M2 = \"M2\", R1 = \"R1\", R2 = \"R2\" }\n -- Job icons ship with the profile: LuaMods\\TensorReactions\\Images\\NAURRoster\\<Job>.png (no addon needed).\n R.icons = {}\n function R.drawIcon(job, size)\n  local path = R.icons[job]\n  if path == nil then\n   local name = JOBNAME[job]\n   path = name and (GetLuaModsPath() .. [[TensorReactions\\Images\\NAURRoster\\]] .. name .. \".png\") or false\n   if path and not FileExists(path) then path = false end\n   R.icons[job] = path\n  end\n  if path then GUI:Image(path, size, size) end\n end\n local function roleColor(slot)\n  local c = slot:sub(1, 1)\n  if c == \"T\" then return 0.45, 0.62, 1.00 elseif c == \"H\" then return 0.40, 0.82, 0.40 end\n  return 0.95, 0.38, 0.38\n end\n local function swap(s, a, b)\n  if not a or not b or a == b then return end\n  local rec = recordOf(s)\n  rec[a], rec[b] = rec[b], rec[a]\n  R.records[s.party] = rec\n  R.save()\n  R.cache = nil\n end\n function R.draw()\n  -- Open once on entering the instance: a new map, or the profile wasn't drawing for a while (we were outside).\n  local now = os.clock()\n  local map = Player and Player.localmapid\n  if map and map ~= R.openedMap then R.show = true end -- v6 (2026-11-13): auto-open only when entering the instance, not after a wipe/reset gap\n  R.openedMap = map or R.openedMap\n  R.lastDraw = now\n  if not R.show then R.drag = nil return end\n  local visible, open = GUI:Begin(\"Party Roster###NAURPartyRoster\", true, GUI.WindowFlags_AlwaysAutoResize)\n  if visible then\n   local s = R.enabled and R.state()\n   GUI:PushStyleVar(GUI.StyleVar_FrameRounding, 6)\n   GUI:PushStyleColor(GUI.Col_Button, 0.20, 0.22, 0.32, 1)\n   GUI:PushStyleColor(GUI.Col_ButtonHovered, 0.20, 0.22, 0.32, 1)\n   GUI:PushStyleColor(GUI.Col_ButtonActive, 0.20, 0.22, 0.32, 1)\n   GUI:Button(\"Roster##NAURRosterPill\")\n   GUI:PopStyleColor(3)\n   GUI:SameLine()\n   if not R.enabled then\n    GUI:Text(\"Off - the draws use Anyone's Party Roster.\")\n   elseif not s then\n    GUI:Text(\"Waiting for 8 party members (Anyone's roster until then).\")\n   elseif s.saved then\n    GUI:Text(\"Saved roster for this party.\")\n   else\n    GUI:Text(\"New party - seated by \" .. (R.inTop() and (R.region .. \" rules\") or \"role\") .. \". Confirm or adjust.\")\n   end\n   local on, onChanged = GUI:Checkbox(\"Use this roster##NAURRosterOn\", R.enabled)\n   if onChanged then R.enabled = on; R.cache = nil; R.save() end\n   if GUI:IsItemHovered() then GUI:SetTooltip(\"Off: the draws use Anyone's Party Roster.\") end\n   GUI:SameLine()\n   if GUI:Button(\"Anyone's roster##NAURRosterAnyone\") and AnyoneCore and AnyoneCore.RosterPopup and AnyoneCore.RosterPopup.openManual then\n    AnyoneCore.RosterPopup.openManual()\n   end\n   if R.inTop() then\n    GUI:Text(\"Region: \" .. tostring(R.region) .. \" (follows the Preset)\")\n    if GUI:IsItemHovered() then GUI:SetTooltip(\"NA: caster R1, physical ranged R2.\\nElemental, OCE, LPDU, Mana: physical ranged R1, caster R2.\") end\n   end\n   if s then\n    local W, H = 320, 34\n    local mx, my = GUI:GetMousePos()\n    local rects = {}\n    for _, slot in ipairs(R.slots) do\n     local row = s.bySlot[slot]\n     local x, y = GUI:GetCursorScreenPos()\n     rects[slot] = { x, y, x + W, y + H }\n     local over = R.drag and R.drag ~= slot and mx and mx >= x and mx <= x + W and my >= y and my <= y + H\n     local base = (R.drag == slot and 0.24) or (over and 0.30) or 0.14\n     GUI:PushStyleColor(GUI.Col_Button, base, base, base + 0.03, 1)\n     GUI:PushStyleColor(GUI.Col_ButtonHovered, 0.20, 0.20, 0.24, 1)\n     GUI:PushStyleColor(GUI.Col_ButtonActive, 0.24, 0.24, 0.28, 1)\n     GUI:Button(\"##NAURRosterRow\" .. slot, W, H)\n     GUI:PopStyleColor(3)\n     if GUI:IsItemActive() and GUI:IsMouseDragging(0) then R.drag = R.drag or slot end\n     if GUI:IsItemHovered() and not R.drag then GUI:SetTooltip(row.name) end\n     if GUI:IsItemClicked(1) then R.pick = slot; GUI:OpenPopup(\"NAURRosterPick\") end\n     local r, g, b = roleColor(slot)\n     GUI:SetCursorScreenPos(x + 14, y + 9)\n     GUI:TextColored(r, g, b, 1, LABEL[slot])\n     if row.job then\n      GUI:SetCursorScreenPos(x + 50, y + 4)\n      R.drawIcon(row.job, 26)\n     end\n     GUI:SetCursorScreenPos(x + 88, y + 9)\n     GUI:Text(JOBNAME[row.job] or tostring(row.job))\n     GUI:SetCursorScreenPos(x, y + H + 5)\n    end\n    GUI:Dummy(W, 1)\n    if R.drag and not GUI:IsMouseDown(0) then\n     for slot, rc in pairs(rects) do\n      if mx and mx >= rc[1] and mx <= rc[3] and my >= rc[2] and my <= rc[4] then swap(s, R.drag, slot) break end\n     end\n     R.drag = nil\n    end\n    if GUI:BeginPopup(\"NAURRosterPick\") then\n     GUI:Text((LABEL[R.pick] or \"?\") .. \" is:\")\n     for _, row in ipairs(s.list) do\n      local a, c = GUI:Selectable((JOBNAME[row.job] or \"?\") .. \"  \" .. row.name .. \"##NAURPick\" .. row.key, row.slot == R.pick)\n      if (c == nil and a) or c then swap(s, R.pick, row.slot); GUI:CloseCurrentPopup() end\n     end\n     GUI:EndPopup()\n    end\n    if GUI:Button(\"Default Order##NAURRosterAuto\", 104, 26) then R.records[s.party] = nil; R.save(); R.cache = nil end\n    if GUI:IsItemHovered() then GUI:SetTooltip(\"Forget this party's saved roster and seat by role (TOP: by the Region).\") end\n    GUI:SameLine()\n    if GUI:Button(\"Confirm##NAURRosterSave\", 104, 26) then R.records[s.party] = recordOf(s); R.save(); R.cache = nil; R.show = false; R.drag = nil end\n    GUI:SameLine()\n    if GUI:Button(\"Show labels##NAURRosterLabels\", 104, 26) and AnyoneCore and AnyoneCore.addTimedWorldTextOnEnt then\n     for _, slot in ipairs(R.slots) do AnyoneCore.addTimedWorldTextOnEnt(5000, LABEL[slot], s.bySlot[slot].id, 0xFFFFFFFF, true, 1.8, 0.3) end\n    end\n    GUI:TextColored(0.55, 0.55, 0.6, 1, \"Drag a row onto another to swap. Right-click for a direct pick.\")\n   end\n   GUI:PopStyleVar(1)\n  end\n  GUI:End()\n  if open == false then R.show = false; R.drag = nil end\n end\n setmetatable(R, { __index = function(_, k) local a = anyone() return a and a[k] end })\n NAUR_Roster = R\nend\nNAUR_Roster.draw()\n\n-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 41 then\n    cfg = {\n        version = 41,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- Mana: arrow to my Wave Cannon Kyrios spot after Pantokrator.\n            kyrArrow = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Line colour for the \"Tether\" style (the user, 2026-11-15; it used to come out white).\n            tetherColor = \"Red\",\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Tether line colours (ABGR). Every colour slot of the line drawer gets the same one: with a white outline slot the\n    -- line came out white.\n    cfg.TETHER_COLOR_NAMES = { \"Red\", \"Orange\", \"Yellow\", \"Green\", \"Cyan\", \"Blue\", \"Magenta\", \"White\" }\n    cfg.TETHER_COLORS = { Red = 0xFF0000FF, Orange = 0xFF0088FF, Yellow = 0xFF00FFFF, Green = 0xFF00FF00, Cyan = 0xFFFFFF00,\n                          Blue = 0xFFFF0000, Magenta = 0xFFFF00FF, White = 0xFFFFFFFF }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                local colors = live.TETHER_COLORS or {}\n                local color = colors[live.values.tetherColor] or 0xFF0000FF\n                live.tetherDrawers = live.tetherDrawers or {}\n                local drawer = live.tetherDrawers[color]\n                if drawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    drawer = TensorCore.getCachedDrawer(color, color, color, color, 2, 0, overlay)\n                    live.tetherDrawers[color] = drawer\n                end\n                drawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() and not (Roster.state and Roster.state()) then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        local naur = Roster.state and Roster.state()\n        if naur then\n            saved = { members = {}, jobs = {} }\n            for slot, row in pairs(naur.bySlot) do saved.members[row.key] = slot; saved.jobs[row.key] = row.job end\n        end\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\nif data.topLooperOptionsClosed then\n    self.used = true\n    return\nend\nif cfg.sections == nil then\n    -- A row with a range is a slider; without one it is a checkbox; \"style\" makes an Arrow/Tether choice; \"choice\" picks from\n    -- the list in the row's 4th field. A new setting only\n    -- needs a row and a default.\n    -- In fight order. Each section runs arrow, spots, labels, then warnings and extras; draws that overlap something else are off by default.\n    cfg.sections = {\n        { \"All mechanics\", {\n            { \"rosterOpen\", \"Open Party Roster at the start\" },\n            { \"labelSize\", \"Spot label size\", 1, 3, \"%.1f\" },\n            { \"tts\", \"Callout text-to-speech\" },\n            { \"mitOn\", \"Mitigation (from the mit sheet)\" },\n        } },\n        { \"P1  Program Loop\", {\n            { \"arrow\", \"Arrow##loop\" },\n            { \"stLoop\", \"Arrow or tether##loop\", \"style\" },\n            { \"nextRing\", \"Next-spot ring\" },\n            { \"callouts\", \"Callouts\" },\n            { \"topUp\", \"Tank/healer top-up reminder\" },\n            { \"tetherRadius\", \"Tether spot distance (y)\", 12, 19, \"%.1f\" },\n            { \"tetherAngle\", \"Tether cheat angle (deg)\", 0, 14, \"%.0f\" },\n            { \"grabDistance\", \"Tether grab distance from boss (y)\", 2, 9, \"%.1f\" },\n            { \"towerOffset\", \"Tower off-centre (y)\", 0, 2.5, \"%.1f\" },\n        } },\n        { \"P1  Pantokrator\", {\n            { \"panCallouts\", \"Flex and bait callouts\" },\n        } },\n        { \"P2  Party Synergy\", {\n            { \"synArrow\", \"Arrow##syn\" },\n            { \"stSyn\", \"Arrow or tether##syn\", \"style\" },\n            { \"synSpots\", \"Spots##syn\" },\n            { \"synLabels\", \"My label##syn\" },\n            { \"synOthers\", \"Other roles' labels##syn\" },\n            { \"synFlex\", \"Flex reminder\" },\n            { \"synFlexRule\", \"Which stack flexes\", \"choice\", { \"Strat default\", \"Closest to eye\", \"Furthest from eye\" } },\n            { \"synKnock\", \"Knockback spots\" },\n            { \"synAoe\", \"Optical Laser draw (boss attack)\" },\n        } },\n        { \"P2  Limitless Synergy\", {\n            { \"limTank\", \"Tank tether arrow\" },\n            { \"limAoe\", \"Sagittarius Arrow draw (boss attack)\" },\n            { \"stLim\", \"Arrow or tether##lim\", \"style\" },\n        } },\n        { \"P3  Intermission\", {\n            { \"intArrow\", \"Arrow##int\" },\n            { \"stInt\", \"Arrow or tether##int\", \"style\" },\n            { \"intSpots\", \"Spots##int\" },\n            { \"intLabels\", \"Labels##int\" },\n        } },\n        { \"P3  Hello World\", {\n            { \"helArrow\", \"Arrow##hel\" },\n            { \"stHel\", \"Arrow or tether##hel\", \"style\" },\n            { \"helSpots\", \"Spots##hel\" },\n            { \"helLabels\", \"Labels##hel\" },\n            { \"helConga\", \"Conga spots after Critical Error\" },\n        } },\n        { \"P3  Monitors\", {\n            { \"monArrow\", \"Arrow##mon\" },\n            { \"stMon\", \"Arrow or tether##mon\", \"style\" },\n            { \"monRing\", \"Ring##mon\" },\n            { \"monFace\", \"Face lock##mon\" },\n            { \"monFacing\", \"Facing line (if not face locking)\" },\n            { \"monSouth\", \"Monitor 3 extra south (y)\", 0, 5, \"%.1f\" },\n        } },\n        { \"P4  Wave Cannons\", {\n            { \"wcAoe\", \"Wave Cannon line draws (boss attack)\" },\n        } },\n        { \"P5  Delta\", {\n            { \"delArrow\", \"Arrow##del\" },\n            { \"stDel\", \"Arrow or tether##del\", \"style\" },\n            { \"delSpots\", \"Spots##del\" },\n            { \"delLabels\", \"My label##del\" },\n            { \"delOthers\", \"Other roles' labels##del\" },\n            { \"delBreak\", \"Tether break warning\" },\n            { \"delSwap\", \"Fist swap reminder\" },\n            { \"delMonitor\", \"Monitor guidance\" },\n            { \"delFace\", \"Face lock##del\" },\n            { \"delOtherBeams\", \"Other players' monitor beams\" },\n            { \"delBossHalf\", \"Final Omega's monitor half\" },\n            { \"delAoe\", \"Optical Laser and fist puddle draws (boss attacks)\" },\n        } },\n        { \"P5  Sigma\", {\n            { \"sigArrow\", \"Arrow##sig\" },\n            { \"stSig\", \"Arrow or tether##sig\", \"style\" },\n            { \"sigSpots\", \"Spots##sig\" },\n            { \"sigLabels\", \"My label##sig\" },\n            { \"sigOthers\", \"Other roles' labels##sig\" },\n            { \"sigAoe\", \"Rear Lasers draw (boss attack)\" },\n        } },\n        { \"P5  Omega\", {\n            { \"omeArrow\", \"Arrow##ome\" },\n            { \"stOme\", \"Arrow or tether##ome\", \"style\" },\n            { \"omeSpots\", \"Spots##ome\" },\n            { \"omeLabels\", \"Labels##ome\" },\n            { \"omeClones\", \"Clone attack predraws (your MuAi cones cover it)\" },\n            { \"omeSafe\", \"  Clone predraws as safe area (off: red attacks)\" },\n            { \"omePreview\", \"  Preview the next pair (red attacks)\" },\n        } },\n        { \"P5  World bounces\", {\n            { \"worldDraw\", \"Near/Far bounce prediction\" },\n        } },\n        { \"P6  Exasquares\", {\n            { \"exaArrow\", \"Dodge arrow##exa\" },\n            { \"stExa\", \"Arrow or tether##exa\", \"style\" },\n            { \"exaDpsSupport\", \"  Side dodges##exa\" },\n            { \"exaZone\", \"Line draws##exa\" },\n            { \"exaSafe\", \"  Line draws as safe area (off: red lines)##exa\" },\n        } },\n        { \"P6  Unlimited Wave Cannon\", {\n            { \"uwcArrow\", \"Exaflare puddle arrow (both)\" },\n            { \"stUwc\", \"Arrow or tether##uwc\", \"style\" },\n        } },\n        { \"P6  Clock spots\", {\n            { \"clkWave\", \"Wave Cannon 1 clock spot arrow\" },\n            { \"clkMeteor\", \"Cosmo Meteor arrow\" },\n            { \"clkFlare\", \"Flare marker arrow\" },\n            { \"stClk\", \"Arrow or tether##clk\", \"style\" },\n        } },\n    }\n    -- The user's settings on 2026-11-08, saved as the NA preset. Every row has a value here.\n    cfg.presets = {\n        NA = {\n            rosterOpen = false, labelSize = 1.5, tts = false, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            arrow = true, nextRing = true, callouts = false, topUp = false,\n            tetherRadius = 16, tetherAngle = 0, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true, kyrArrow = true,\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            synFlexRule = \"Strat default\",\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = false, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n    }\nend\nlocal values = cfg.values\nif NAUR_Roster then NAUR_Roster.presetOf = function() return values.mana and \"Mana\" or values.ldpu and \"LPDU\" or values.oce and \"OCE\" or values.elemental and \"Elemental\" or \"NA\" end end\nlocal visible, open = GUI:Begin(\"Masado's draws###TopLooperOptions\", true, GUI.WindowFlags_AlwaysAutoResize)\nif visible then\n    local Roster = NAUR_Roster or (AnyoneCore and AnyoneCore.Roster)\n    if Roster ~= nil and Roster.current() ~= nil then\n        local slot = Roster.mySlot()\n        local base = (slot == \"H1\" or slot == \"R1\" or slot == \"M1\" or slot == \"T1\") and \"G1\" or \"G2\"\n        GUI:TextColored(0.4, 1, 0.4, 1, \"Party Roster: \" .. tostring(slot) .. \", base group \" .. base)\n    else\n        GUI:TextColored(1, 0.4, 0.4, 1, \"Party Roster not set: flex and role spots won't work\")\n    end\n    -- Opens our NAUR roster window when it is loaded, Anyone's popup otherwise (the user, 2026-11-15).\n    local popup = AnyoneCore and AnyoneCore.RosterPopup\n    if (NAUR_Roster or (popup and popup.openManual)) and GUI:Button(\"Edit Party Roster\") then\n        if NAUR_Roster then NAUR_Roster.show = true else popup.openManual() end\n    end\n    GUI:Spacing()\n    -- Strat presets, laid out like Frog Draws on DSR: plain name buttons, the strat in use drawn green. NA applies the user's\n    -- saved settings (NA guides); Elemental (ffxiv.tuufless.com/elemental/top) and OCE (materiaraiding.com/ultimate/top)\n    -- only switch the strat, for the solvers that have it. LPDU is the user's name for the raidplan/toolbox guides (2026-11-08).\n    -- One option row (the user, 2026-11-23): the name on the left, a dropdown lined up on the right. Returns the picked index.\n    local function optRow(label, id, current, items)\n        GUI:Text(label)\n        GUI:SameLine(230)\n        GUI:PushItemWidth(150)\n        local picked = GUI:Combo(\"##\" .. id, current, items)\n        GUI:PopItemWidth()\n        return picked\n    end\n    -- Mana: the JP Mana guide (lodestone blog 5536808).\n    local current = values.mana and \"Mana\" or values.ldpu and \"LPDU\" or values.oce and \"OCE\" or values.elemental and \"Elemental\" or \"NA\"\n    local strats = { \"NA\", \"Elemental\", \"OCE\", \"LPDU\", \"Mana\" }\n    local cur = 1\n    for i, strat in ipairs(strats) do if strat == current then cur = i end end\n    local pick = optRow(\"Preset\", \"TopStrat\", cur, strats)\n    if pick ~= cur and strats[pick] then\n        local strat = strats[pick]\n        if strat == \"NA\" then\n            for key, value in pairs(cfg.presets.NA) do\n                if cfg.defaults[key] ~= nil then values[key] = value end\n            end\n        end\n        values.elemental = strat == \"Elemental\"\n        values.oce = strat == \"OCE\"\n        values.ldpu = strat == \"LPDU\"\n        values.mana = strat == \"Mana\"\n        cfg.dirty = true\n    end\n    -- LPDU's second Exasquare already uses the \"Side dodges\" layout, so the box shows ticked while LPDU is the preset (the user,\n    -- 2026-11-11). It changes nothing there; the NA preset button puts it back to the saved NA choice.\n    if values.ldpu and not values.exaDpsSupport then\n        values.exaDpsSupport = true\n        cfg.dirty = true\n    end\n    -- The NA mit sheet plan ([Mit] reactions) on or off, styled like the presets (the user, 2026-11-08): the one in use drawn green.\n    do\n        local pick = optRow(\"Mitigation\", \"TopMit\", values.mitOn and 1 or 2, { \"NA\", \"Off\" })\n        if (pick == 1) ~= (values.mitOn == true) then values.mitOn = pick == 1 cfg.dirty = true end\n    end\n    -- Tank mitigation (the user, 2026-11-22): the [Tank Mit] reactions for the Warrior, Reprisal/Shake It Off from TOP Mitty plus the personal\n    -- mits and Provoke/Shirk of Warrior MT test. Off by default. Saved on its own (TOP-TankMit.lua): the settings block only keeps its own keys.\n    local tank = data.topTankMit\n    if tank == nil then\n        local path = GetLuaModsPath() .. [[TensorReactions\\Settings\\TOP-TankMit.lua]]\n        local saved = FileExists(path) and FileLoad(path)\n        tank = { path = path, on = type(saved) == \"table\" and saved.on == true }\n        data.topTankMit = tank\n    end\n    do\n        local pick = optRow(\"Tank mitigation\", \"TopTankMit\", tank.on and 1 or 2, { \"On\", \"Off\" })\n        if (pick == 1) ~= (tank.on == true) then tank.on = pick == 1 pcall(FileSave, tank.path, { on = tank.on }) end\n    end\n    -- Automarkers (the user, 2026-11-22: \"combine the option into Masado's draws\"): drawn here, written by [AM] Writer (no targeting).\n    local am = data.topAM\n    if am and am.drawOptions then\n        GUI:Spacing()\n        if GUI:CollapsingHeader(\"Automarkers##TopAMHeader\") then am.drawOptions() end\n    else\n        GUI:TextColored(0.55, 0.55, 0.6, 1, \"Automarkers: loading...\")\n    end\n    -- Boss draws (2026-11-22, the user: \"make all of the necessary looking good draws for everything\"): which groups of the\n    -- [Boss AoE] Everything row are drawn. Saved in Settings\\TOP-Draws.lua.\n    GUI:Spacing()\n    if GUI:CollapsingHeader(\"Optional boss draws##TopBossDraws\") then\n            local D = data.topDraws\n            if D == nil then\n                local path = GetLuaModsPath() .. [[TensorReactions\\Settings\\TOP-Draws.lua]]\n                local saved = FileExists(path) and FileLoad(path)\n                D = { path = path, values = type(saved) == \"table\" and saved or {} }\n                D.defaults = { all = true, weapons = true, p2tank = true, p5 = true, p6 = true, p1 = false, p3 = false, rings = true, masado = true }\n                function D.on(group)\n                    local v = D.values[group]\n                    if v == nil then v = D.defaults[group] end\n                    return v == true\n                end\n                data.topDraws = D\n            end\n        -- The necessary draws are always on (no options); only the two groups the user removed earlier stay switchable. Saved \"off\" values of the\n        -- always-on groups are cleared once.\n        if not D.cleaned then\n            D.cleaned = true\n            local dirty\n            for _, key in ipairs({ \"all\", \"weapons\", \"p2tank\", \"p5\", \"p6\", \"rings\", \"masado\", \"lpdu\" }) do\n                if D.values[key] == false then D.values[key] = nil dirty = true end\n            end\n            if dirty then pcall(FileSave, D.path, D.values) end\n        end\n        local groups = {\n            { \"p1\", \"P1 Pantokrator flamethrowers and missile puddles\" },\n            { \"p3\", \"P3 Wave Repeater rings and hand slams, Hello World circles\" },\n        }\n        for _, g in ipairs(groups) do\n            local cur = D.on(g[1]) and 1 or 2\n            local pick = optRow(g[2], \"TopDraw\" .. g[1], cur, { \"Enabled\", \"Disabled\" })\n            if pick ~= cur then\n                D.values[g[1]] = pick == 1\n                pcall(FileSave, D.path, D.values)\n            end\n        end\n    end\n    -- Auto LB (the user, 2026-11-23): the caster LB3 at Cosmo Meteor and the phys ranged LB3 after it. Default On, saved in TOP-AutoLB.lua.\n    local autoLB = data.topAutoLB\n    if autoLB == nil then\n        local path = GetLuaModsPath() .. [[TensorReactions\\Settings\\TOP-AutoLB.lua]]\n        local saved = FileExists(path) and FileLoad(path)\n        autoLB = { path = path, on = not (type(saved) == \"table\" and saved.on == false) }\n        data.topAutoLB = autoLB\n    end\n    do\n        local pick = optRow(\"Auto LB\", \"TopAutoLB\", autoLB.on and 1 or 2, { \"On\", \"Off\" })\n        if (pick == 1) ~= (autoLB.on == true) then autoLB.on = pick == 1 pcall(FileSave, autoLB.path, { on = autoLB.on }) end\n    end\n    -- Like Frog Draws' \"Quick style\": every mechanic's guide as arrows or as tethers. Lit when they all match.\n    do\n        local allArrow, allTether = true, true\n        for _, key in ipairs(cfg.STYLE_KEYS) do\n            if values[key] ~= \"Arrow\" then allArrow = false end\n            if values[key] ~= \"Tether\" then allTether = false end\n        end\n        local items = { \"All arrows\", \"All tethers\", \"Mixed\" }\n        local cur = allArrow and 1 or allTether and 2 or 3\n        local pick = optRow(\"Quick style\", \"TopStyle\", cur, items)\n        if pick ~= cur and pick <= 2 then\n            for _, key in ipairs(cfg.STYLE_KEYS) do values[key] = pick == 1 and \"Arrow\" or \"Tether\" end\n            cfg.dirty = true\n        end\n    end\n    -- Colour of the \"Tether\" lines, for every mechanic (the user, 2026-11-15).\n    GUI:PushItemWidth(170)\n    local names = cfg.TETHER_COLOR_NAMES\n    local currentColor = 1\n    for i, name in ipairs(names) do\n        if name == values.tetherColor then currentColor = i end\n    end\n    GUI:Text(\"Tether colour\")\n    GUI:SameLine(230)\n    local pickedColor = GUI:Combo(\"##TopTetherColor\", currentColor, names)\n    if pickedColor ~= currentColor and names[pickedColor] then\n        values.tetherColor = names[pickedColor]\n        cfg.dirty = true\n    end\n    GUI:PopItemWidth()\n    GUI:Spacing()\n    GUI:PushItemWidth(150)\n    for _, section in ipairs(cfg.sections) do\n        if GUI:CollapsingHeader(section[1]) then\n            GUI:Indent()\n            for _, row in ipairs(section[2]) do\n                local value, changed\n                -- Row look (the user, 2026-11-23, screenshot): the name on the left, a dropdown lined up on the right.\n                local label = tostring(row[2]):gsub(\"##.*$\", \"\")\n                local id = \"##TopOpt\" .. tostring(row[1])\n                GUI:Text(label)\n                GUI:SameLine(230)\n                if row[3] == nil then\n                    local items = { \"Enabled\", \"Disabled\" }\n                    local current = values[row[1]] and 1 or 2\n                    local picked = GUI:Combo(id, current, items)\n                    if picked ~= current and items[picked] then value, changed = picked == 1, true end\n                elseif row[3] == \"style\" then\n                    -- Frog Draws' per-mechanic style: Arrow or Tether.\n                    local items = { \"Arrow\", \"Tether\" }\n                    local current = values[row[1]] == \"Tether\" and 2 or 1\n                    local picked = GUI:Combo(id, current, items)\n                    if picked ~= current and items[picked] then value, changed = items[picked], true end\n                elseif row[3] == \"choice\" then\n                    local items = row[4]\n                    local current = 1\n                    for i, item in ipairs(items) do\n                        if item == values[row[1]] then current = i end\n                    end\n                    local picked = GUI:Combo(id, current, items)\n                    if picked ~= current and items[picked] then value, changed = items[picked], true end\n                else\n                    value, changed = GUI:SliderFloat(id, values[row[1]], row[3], row[4], row[5])\n                end\n                if changed then\n                    values[row[1]] = value\n                    cfg.dirty = true\n                end\n            end\n            GUI:Unindent()\n            GUI:Spacing()\n        end\n    end\n    GUI:PopItemWidth()\n    GUI:Spacing()\n    if GUI:Button(\"Reset to defaults\") then\n        for key, default in pairs(cfg.defaults) do\n            values[key] = default\n        end\n        cfg.dirty = true\n    end\n    -- Callout text-to-speech on or off, one click from the bottom of the window.\n    GUI:SameLine()\n    if GUI:Button(values.tts and \"TTS: On###TopTts\" or \"TTS: Off###TopTts\") then\n        values.tts = not values.tts\n        cfg.dirty = true\n    end\n    -- Every callout (text and speech) on or off, beside TTS (the user, 2026-11-08).\n    GUI:SameLine()\n    if GUI:Button(values.calloutOn and \"Callouts: On###TopCallouts\" or \"Callouts: Off###TopCallouts\") then\n        values.calloutOn = not values.calloutOn\n        cfg.dirty = true\n    end\nend\n-- Save once a slider is released rather than on every drag step.\nif cfg.dirty and not GUI:IsAnyItemActive() then\n    cfg.dirty = false\n    FileSave(cfg.path, values)\nend\nGUI:End()\nif open == false then\n    data.topLooperOptionsClosed = true\nend\nself.used = true\n",
							name = "Options Window",
