		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- [AM] Writer (2026-11-22). Writes the automarkers; the options are drawn by [Looper] Options (Masado's draws, \"Automarkers\" section).\n-- The user: \"make the Automarkers that doesn't need targeting\": marks go out as /mk <mark> <me> or <2>..<8> (the party-list slot),\n-- so nobody is targeted and the player's own target is never touched. The slot comes from the entity's partyindex, calibrated on my own\n-- partyindex (I am <1>/<me>), and every mark is checked after it is sent. A foreign mark on anyone aborts the set. After each\n-- mechanic the marks THIS writer placed are cleared again (/mk off <slot>); marks it didn't place are never touched.\n-- Settings file: TensorReactions\\Settings\\TOP-Automarkers.lua (unchanged). Everything is OFF by default.\nlocal store = data.topAMStore\nif store == nil then\n    local path = GetLuaModsPath() .. [[TensorReactions\\Settings\\TOP-Automarkers.lua]]\n    local values = {}\n    if FileExists(path) then\n        local saved = FileLoad(path)\n        if type(saved) == \"table\" then values = saved end\n    end\n    store = { path = path, values = values }\n    function store.save()\n        local folder = GetLuaModsPath() .. [[TensorReactions\\Settings\\]]\n        if not FolderExists(folder) then FolderCreate(folder) end\n        local ok, why = pcall(FileSave, store.path, store.values)\n        store.error = (not ok) and tostring(why) or nil\n    end\n    data.topAMStore = store\nend\nlocal values = store.values\n\nlocal AM = data.topAM\nif AM ~= nil and AM.version ~= 3 then AM = nil end\nif AM == nil then\n    AM = { store = store, owned = {}, snapshots = {}, snapAt = {}, why = {}, status = \"Off\" }\n    data.topAM = AM\n    AM.version = 3\n    AM.SLOTS = { \"T1\", \"T2\", \"H1\", \"H2\", \"M1\", \"M2\", \"R1\", \"R2\" }\n    -- /mk names for the marker numbers: 1-5 Attack, 6-8 Bind, 9-10 Ignore, 11-14 square/circle/cross/triangle.\n    AM.COMMANDS = { [1] = \"attack1\", [2] = \"attack2\", [3] = \"attack3\", [4] = \"attack4\", [5] = \"attack5\", [6] = \"bind1\", [7] = \"bind2\",\n                    [8] = \"bind3\", [9] = \"ignore1\", [10] = \"ignore2\", [11] = \"square\", [12] = \"circle\", [13] = \"cross\", [14] = \"triangle\" }\n    -- The no-sign numbering each preset's guide uses for the Monitors (same lines as [Monitor] Arrow).\n    AM.LINES = {\n        NA = { \"H1\", \"R1\", \"M1\", \"T1\", \"T2\", \"M2\", \"R2\", \"H2\" },\n        Elemental = { \"H1\", \"H2\", \"T1\", \"T2\", \"M1\", \"M2\", \"R1\", \"R2\" },\n        Mana = { \"T1\", \"T2\", \"M1\", \"M2\", \"R1\", \"R2\", \"H1\", \"H2\" },\n    }\n    AM.LINES.OCE, AM.LINES.LPDU = AM.LINES.NA, { \"R1\", \"M1\", \"T1\", \"H1\", \"H2\", \"T2\", \"M2\", \"R2\" }\n\n    function AM.say(text)\n        AM.status = text\n        d(\"[Automarkers] \" .. text)\n        TensorCore.timelineLogToFile(\"[Automarkers] \" .. text .. \"\\n\")\n    end\n\n    function AM.preset()\n        local c = data.topLooperSettings\n        local v = c and c.values\n        if v == nil then return nil end\n        return v.mana and \"Mana\" or v.ldpu and \"LPDU\" or v.oce and \"OCE\" or v.elemental and \"Elemental\" or \"NA\"\n    end\n\n    function AM.party()\n        local Roster = NAUR_Roster or (AnyoneCore and AnyoneCore.Roster)\n        if Roster == nil or Roster.current() == nil then return nil, \"no Party Roster\" end\n        local party = {}\n        for rank, slot in ipairs(AM.SLOTS) do\n            local e = Roster.entOf(slot)\n            if e == nil or e.id == nil then return nil, \"the Party Roster has no \" .. slot end\n            party[#party + 1] = { slot = slot, rank = rank, id = e.id }\n        end\n        return party\n    end\n\n    -- Builders: return the list { id, marker } or nil and why not. One snapshot per mechanic per pull.\n    function AM.buildMonitor()\n        local preset = AM.preset()\n        if preset == nil then return nil, \"preset unknown (the Looper Options haven't loaded)\" end\n        local party, why = AM.party()\n        if party == nil then return nil, why end\n        local bySlot = {}\n        for _, p in ipairs(party) do bySlot[p.slot] = p end\n        local queue, monitors, others = {}, 0, 0\n        for _, slot in ipairs(AM.LINES[preset]) do\n            local p = bySlot[slot]\n            if TensorCore.hasBuff(p.id, 3452) or TensorCore.hasBuff(p.id, 3453) then\n                monitors = monitors + 1\n                queue[#queue + 1] = { id = p.id, marker = 5 + monitors }\n            else\n                others = others + 1\n                queue[#queue + 1] = { id = p.id, marker = others }\n            end\n        end\n        if monitors ~= 3 then return nil, string.format(\"%d monitor debuffs seen, expected 3\", monitors) end\n        return queue\n    end\n\n    function AM.buildTransition()\n        local party, why = AM.party()\n        if party == nil then return nil, why end\n        local groups = { {}, {}, {} }\n        for _, p in ipairs(party) do\n            local e = TensorCore.mGetEntity(p.id)\n            if e == nil or e.pos == nil then return nil, \"a player isn't visible\" end\n            p.x = e.pos.x\n            local category = TensorCore.hasBuff(p.id, 3425) and 1 or TensorCore.hasBuff(p.id, 3426) and 2 or 3\n            groups[category][#groups[category] + 1] = p\n        end\n        if #groups[1] ~= 4 or #groups[2] ~= 2 or #groups[3] ~= 2 then\n            return nil, string.format(\"spread %d, stack %d, none %d (expected 4/2/2)\", #groups[1], #groups[2], #groups[3])\n        end\n        local queue = {}\n        for category, group in ipairs(groups) do\n            table.sort(group, function(a, b)\n                if math.abs(a.x - b.x) > 0.1 then return a.x < b.x end\n                return a.rank < b.rank\n            end)\n            -- Spreads Attack 1-4 left to right, stack pair Bind 1/2, the others Ignore 1/2 (left pair 1, right pair 2).\n            local first = category == 1 and 0 or category == 2 and 5 or 8\n            if category == 3 then first = 8 end\n            for i, p in ipairs(group) do queue[#queue + 1] = { id = p.id, marker = first + i } end\n        end\n        return queue\n    end\n\n    -- P5 (Lemegeton, UltOmegaProtocol.cs: DynamisDeltaAM / DynamisSigmaAM / DynamisOmegaAM). Statuses: Near World 3442, Distant World\n    -- 3443, Quickening Dynamis 3444 (stacks), In Line 1 = 3004, In Line 2 = 3005. Priority order = the Party Roster order.\n    -- NA, OCE and LPDU use the plugin's \"LPDU\" preset (what our solvers read for them); Elemental keeps the plugin's choice of who\n    -- but the marks our Elemental solver reads (the guide image: Attack 1/2 arms, Ignore 1/2 distant baits, Bind 1/2 near baits,\n    -- relabelled Omega signs), and no marks for the World players because their marks would clash. Mana: no rule.\n    AM.P5 = {\n        LPDU = {\n            Delta = { Distant = 13, Near = 14 },\n            Sigma = { Arm = { 6, 7 }, Distant = 13, Near = 14, Far = 1, Close = 4, Near1 = 2, Near2 = 3 },\n            Omega = { Monitor = { 6, 7 }, Distant = 13, Near = 14, Bait = { 1, 2, 3, 4 } },\n        },\n        Elemental = {\n            Delta = { Distant = 10, Near = 9 },\n            Sigma = { Arm = { 1, 2 }, Far = 9, Close = 10, Near1 = 6, Near2 = 7 },\n            Omega = { Monitor = { 1, 2 }, Bait = { 9, 6, 7, 10 } },\n        },\n    }\n\n    function AM.p5rules(phase)\n        local preset = AM.preset()\n        if preset == nil then return nil, \"preset unknown (the Looper Options haven't loaded)\" end\n        if preset == \"Mana\" then return nil, \"no rule for the Mana preset\" end\n        return AM.P5[preset == \"Elemental\" and \"Elemental\" or \"LPDU\"][phase]\n    end\n\n    function AM.stacks(id)\n        local buff = TensorCore.getBuff(id, 3444)\n        return buff and (buff.stacks or 1) or 0\n    end\n\n    function AM.withBuff(party, buffId)\n        local list = {}\n        for _, p in ipairs(party) do\n            if TensorCore.hasBuff(p.id, buffId) then list[#list + 1] = p end\n        end\n        return list\n    end\n\n    -- The party members that are none of the given ids, in roster order.\n    function AM.pick(party, ...)\n        local skip, list = {}, {}\n        for _, id in ipairs({ ... }) do skip[id] = true end\n        for _, p in ipairs(party) do\n            if not skip[p.id] then list[#list + 1] = p end\n        end\n        return list\n    end\n\n    function AM.worlds(party)\n        local near, far = AM.withBuff(party, 3442), AM.withBuff(party, 3443)\n        if #near ~= 1 or #far ~= 1 then\n            return nil, nil, string.format(\"%d Near and %d Distant World debuffs seen, expected 1 each\", #near, #far)\n        end\n        return near[1].id, far[1].id\n    end\n\n    function AM.buildDelta()\n        local rules, why = AM.p5rules(\"Delta\")\n        if rules == nil then return nil, why end\n        local party, w = AM.party()\n        if party == nil then return nil, w end\n        local nearId, farId, bad = AM.worlds(party)\n        if nearId == nil then return nil, bad end\n        return { { id = farId, marker = rules.Distant }, { id = nearId, marker = rules.Near } }\n    end\n\n    function AM.buildSigma()\n        local rules, why = AM.p5rules(\"Sigma\")\n        if rules == nil then return nil, why end\n        local party, w = AM.party()\n        if party == nil then return nil, w end\n        local nearId, farId, bad = AM.worlds(party)\n        if nearId == nil then return nil, bad end\n        local queue = {}\n        if rules.Distant then queue[#queue + 1] = { id = farId, marker = rules.Distant } end\n        if rules.Near then queue[#queue + 1] = { id = nearId, marker = rules.Near } end\n        -- Players with exactly one Dynamis stack and no World debuff, in priority order: Arm 1, Arm 2, Distant far bait.\n        local withStack = {}\n        for _, p in ipairs(AM.pick(party, nearId, farId)) do\n            if AM.stacks(p.id) == 1 then withStack[#withStack + 1] = p end\n        end\n        if #withStack < 3 then return nil, string.format(\"%d players with one Dynamis stack, need 3\", #withStack) end\n        -- The other three (priority order): Distant close bait, Near bait 1, Near bait 2.\n        local rest = AM.pick(party, nearId, farId, withStack[1].id, withStack[2].id, withStack[3].id)\n        if #rest ~= 3 then return nil, string.format(\"%d players left for the baits, need 3\", #rest) end\n        queue[#queue + 1] = { id = withStack[1].id, marker = rules.Arm[1] }\n        queue[#queue + 1] = { id = withStack[2].id, marker = rules.Arm[2] }\n        queue[#queue + 1] = { id = withStack[3].id, marker = rules.Far }\n        queue[#queue + 1] = { id = rest[1].id, marker = rules.Close }\n        queue[#queue + 1] = { id = rest[2].id, marker = rules.Near1 }\n        queue[#queue + 1] = { id = rest[3].id, marker = rules.Near2 }\n        return queue\n    end\n\n    -- Returns set 1 (placed at once) and stores set 2 in AM.snapshots.omega2 (placed after the first Hello, Distant World).\n    function AM.buildOmega()\n        local rules, why = AM.p5rules(\"Omega\")\n        if rules == nil then return nil, why end\n        local party, w = AM.party()\n        if party == nil then return nil, w end\n        local distants, nears = AM.withBuff(party, 3443), AM.withBuff(party, 3442)\n        local firsts, seconds = AM.withBuff(party, 3004), AM.withBuff(party, 3005)\n        if #distants ~= 2 or #nears ~= 2 or #firsts ~= 2 or #seconds ~= 2 then\n            return nil, string.format(\"Distant %d, Near %d, In Line 1 %d, In Line 2 %d (expected 2 each)\", #distants, #nears, #firsts, #seconds)\n        end\n        local function both(a, b)\n            for _, x in ipairs(a) do\n                for _, y in ipairs(b) do\n                    if x.id == y.id then return x.id end\n                end\n            end\n        end\n        local d2, n2, d1, n1 = both(seconds, distants), both(seconds, nears), both(firsts, distants), both(firsts, nears)\n        if d1 == nil or n1 == nil or d2 == nil or n2 == nil then return nil, \"the In Line players don't each have a World debuff\" end\n        local stacks = {}\n        for _, p in ipairs(party) do stacks[p.id] = AM.stacks(p.id) end\n        -- Set 1 monitors: the In Line 2 World players with two stacks, else the players with the most stacks (two or more).\n        local monitors = {}\n        if stacks[d2] == 2 then monitors[#monitors + 1] = d2 end\n        if stacks[n2] == 2 then monitors[#monitors + 1] = n2 end\n        if #monitors < 2 then\n            local cands = {}\n            for _, p in ipairs(AM.pick(party, d1, n1, d2, n2)) do\n                if stacks[p.id] >= 2 then cands[#cands + 1] = p end\n            end\n            table.sort(cands, function(a, b)\n                if stacks[a.id] ~= stacks[b.id] then return stacks[a.id] > stacks[b.id] end\n                return a.rank < b.rank\n            end)\n            for _, c in ipairs(cands) do\n                if #monitors < 2 then monitors[#monitors + 1] = c.id end\n            end\n        end\n        if #monitors ~= 2 then return nil, \"can't find two monitors\" end\n        local rankOf = {}\n        for _, p in ipairs(party) do rankOf[p.id] = p.rank end\n        table.sort(monitors, function(a, b) return rankOf[a] < rankOf[b] end)\n        local rest1 = AM.pick(party, monitors[1], monitors[2], d1, n1)\n        if #rest1 ~= 4 then return nil, string.format(\"%d baits in set 1, need 4\", #rest1) end\n        local set1 = { { id = monitors[1], marker = rules.Monitor[1] }, { id = monitors[2], marker = rules.Monitor[2] } }\n        if rules.Distant then set1[#set1 + 1] = { id = d1, marker = rules.Distant } end\n        if rules.Near then set1[#set1 + 1] = { id = n1, marker = rules.Near } end\n        for i, p in ipairs(rest1) do set1[#set1 + 1] = { id = p.id, marker = rules.Bait[i] } end\n        -- Set 2: after set 1's jumps the World and bait players have one more stack; the two with three are the monitors.\n        stacks[d1], stacks[n1] = stacks[d1] + 1, stacks[n1] + 1\n        for _, p in ipairs(rest1) do stacks[p.id] = stacks[p.id] + 1 end\n        local three = {}\n        for _, p in ipairs(party) do\n            if stacks[p.id] == 3 then three[#three + 1] = p end\n        end\n        if #three ~= 2 then return nil, string.format(\"%d players would have three stacks in set 2, need 2\", #three) end\n        local rest2 = AM.pick(party, three[1].id, three[2].id, d2, n2)\n        if #rest2 ~= 4 then return nil, string.format(\"%d baits in set 2, need 4\", #rest2) end\n        local set2 = { { id = three[1].id, marker = rules.Monitor[1] }, { id = three[2].id, marker = rules.Monitor[2] } }\n        if rules.Distant then set2[#set2 + 1] = { id = d2, marker = rules.Distant } end\n        if rules.Near then set2[#set2 + 1] = { id = n2, marker = rules.Near } end\n        for i, p in ipairs(rest2) do set2[#set2 + 1] = { id = p.id, marker = rules.Bait[i] } end\n        AM.snapshots.omega2 = set2\n        return set1\n    end\n\n    function AM.snapshot(key, make)\n        local s = AM.snapshots[key]\n        if s ~= nil then return s end\n        local queue, why = make()\n        if queue then\n            AM.snapshots[key] = queue\n            AM.snapAt[key] = Now()\n            return queue\n        end\n        if why and AM.why[key] ~= why then\n            AM.why[key] = why\n            AM.say(key .. \": waiting, \" .. why)\n        end\n        return nil\n    end\n\n    -- Nothing is targeted any more; kept so the callers stay the same.\n    function AM.restore(w) end\n\n    -- The party-list placeholder for a player: <me> for myself, else <n> = partyindex + (1 - my partyindex). nil when unknown.\n    function AM.partyIndex(id)\n        local e = TensorCore.mGetEntity(id)\n        if e and e.partyindex ~= nil then return e.partyindex end\n        for _, pe in pairs(EntityList.myparty or {}) do\n            if pe and pe.id == id and pe.partyindex ~= nil then return pe.partyindex end\n        end\n        return nil\n    end\n\n    -- Lemegeton (State.cs PerformMarking, command fallback): /mk <sign> <n> where n = the player's position in the party list\n    -- (HUD index + 1), no targeting. Minion's partyindex may start at 0 or 1, so the lowest index in the party decides the offset.\n    function AM.slot(id)\n        local me = TensorCore.mGetPlayer()\n        if me == nil then return nil end\n        if id == me.id then return \"<me>\" end\n        local theirs = AM.partyIndex(id)\n        if theirs == nil then return nil end\n        local low = theirs\n        for _, slot in ipairs(AM.SLOTS) do\n            local R = NAUR_Roster or (AnyoneCore and AnyoneCore.Roster)\n            local e = R and R.entOf(slot)\n            local pi = e and e.id and AM.partyIndex(e.id)\n            if pi ~= nil and pi < low then low = pi end\n        end\n        local n = theirs + (low == 0 and 1 or 0)\n        if n < 1 or n > 8 then return nil end\n        return \"<\" .. n .. \">\"\n    end\n\n    function AM.tick(key, queue, enabled)\n        local w = AM.writer\n        local me = TensorCore.mGetPlayer()\n        if me == nil then return end\n        if not enabled or queue == nil then\n            if w and w.key == key then AM.restore(w) end\n            return\n        end\n        local party = AM.party()\n        if party == nil then return end\n        if w == nil then\n            w = {}\n            AM.writer = w\n        end\n        if w.key ~= key then\n            AM.restore(w)\n            w.key, w.start, w.index, w.pending, w.done, w.blocked = key, Now(), 1, nil, nil, nil\n        end\n        if w.done or w.blocked or Now() - w.start < 1800 then return end\n        local seenMark, seenPlayer = {}, {}\n        for _, a in ipairs(queue) do\n            if seenMark[a.marker] or seenPlayer[a.id] then return end\n            seenMark[a.marker], seenPlayer[a.id] = true, true\n        end\n        -- A foreign mark on anyone aborts the whole set.\n        for _, p in ipairs(party) do\n            local e = TensorCore.mGetEntity(p.id)\n            local pending = w.pending and w.pending.id == p.id and w.pending.marker == (e and e.marker)\n            if e and e.marker and e.marker ~= 0 and AM.owned[p.id] ~= e.marker and not pending then\n                w.blocked = true\n                AM.restore(w)\n                AM.say(key .. \": stopped, someone already has a mark\")\n                return\n            end\n        end\n        if w.pending then\n            local e = TensorCore.mGetEntity(w.pending.id)\n            if e and e.marker == w.pending.marker then\n                AM.owned[e.id] = e.marker\n                w.pending = nil\n                w.index = w.index + 1\n                AM.restore(w)\n            elseif Now() - w.sent > 1200 then\n                w.blocked = true\n                AM.restore(w)\n                AM.say(key .. \": stopped, a mark didn't land\")\n            end\n            return\n        end\n        local nextMark = queue[w.index]\n        if nextMark == nil then\n            w.done = true\n            AM.restore(w)\n            AM.say(key .. \": marks placed\")\n            return\n        end\n        local e = TensorCore.mGetEntity(nextMark.id)\n        if e == nil then\n            w.blocked = true\n            AM.restore(w)\n            AM.say(key .. \": stopped, a player isn't visible\")\n            return\n        end\n        if e.marker == nextMark.marker then\n            w.index = w.index + 1\n            return\n        end\n        local slot = AM.slot(e.id)\n        if slot == nil then\n            w.blocked = true\n            AM.say(key .. \": stopped, no party slot for a player\")\n            return\n        end\n        SendTextCommand(\"/mk \" .. AM.COMMANDS[nextMark.marker] .. \" \" .. slot)\n        w.pending, w.sent = nextMark, Now()\n    end\n\n    -- Clear the marks this writer placed on `ids` (one per step like the writer). Only a mark that is still the one we put\n    -- there is cleared; anything else on anyone is left alone. Returns true when nothing of ours is left on them.\n    function AM.clearTick(key, ids)\n        local c = AM.clearer\n        local me = TensorCore.mGetPlayer()\n        if me == nil then return false end\n        if c == nil or c.key ~= key then\n            AM.restore(c)\n            c = { key = key, start = Now() }\n            AM.clearer = c\n        end\n        if c.done then return true end\n        if c.blocked then return false end\n        local target\n        for _, id in ipairs(ids) do\n            local e = TensorCore.mGetEntity(id)\n            if e and e.marker and e.marker ~= 0 and AM.owned[id] == e.marker then target = e break end\n            if e and (e.marker == nil or e.marker == 0) and AM.owned[id] then AM.owned[id] = nil end\n        end\n        if c.pending then\n            local e = TensorCore.mGetEntity(c.pending)\n            if e == nil or e.marker == nil or e.marker == 0 then\n                AM.owned[c.pending] = nil\n                c.pending = nil\n                AM.restore(c)\n            elseif Now() - c.sent > 1200 then\n                c.blocked = true\n                AM.restore(c)\n                AM.say(key .. \": a mark didn't clear\")\n                return false\n            end\n            return false\n        end\n        if target == nil then\n            c.done = true\n            AM.restore(c)\n            AM.say(key .. \": marks cleared\")\n            return true\n        end\n        local slot = AM.slot(target.id)\n        if slot == nil then\n            c.blocked = true\n            AM.say(key .. \": no party slot to clear a mark\")\n            return false\n        end\n        SendTextCommand(\"/mk off \" .. slot)\n        c.pending, c.sent = target.id, Now()\n        return false\n    end\nend\n\n-- A new pull (the timer drops a lot): forget what was placed.\nlocal t = TensorReactions_CurrentTimer or 0\nif AM.lastTime and t < AM.lastTime - 5 then\n    AM.restore(AM.writer)\n    AM.restore(AM.clearer)\n    -- Marks of ours still up from the last pull (a wipe before the mechanic ended) are cleared first thing.\n    local left = {}\n    for id in pairs(AM.owned) do left[#left + 1] = id end\n    AM.leftover = #left > 0 and left or nil\n    AM.writer, AM.clearer, AM.snapshots, AM.snapAt, AM.why = nil, nil, {}, {}, {}\nend\nAM.lastTime = t\nif AM.leftover and values.enabled == true and values.clear ~= false then\n    if AM.clearTick(\"leftover\", AM.leftover) then AM.leftover = nil end\nend\n\n-- The options, called by [Looper] Options inside its Automarkers section.\nfunction AM.drawOptions()\n    local values = AM.store.values\n    local store = AM.store\n    local changed\n    GUI:TextColored(0.55, 0.55, 0.6, 1, \"Puts the head markers on the party. Off by default.\")\n    GUI:TextColored(0.55, 0.55, 0.6, 1, \"Stops if anyone already has a mark. Clears only its own marks.\")\n    GUI:Spacing()\n    values.enabled, changed = GUI:Checkbox(\"Enable automarkers##AMenabled\", values.enabled == true)\n    if changed then store.save() end\n    if GUI:IsItemHovered() then GUI:SetTooltip(\"Master switch. Nothing is marked while this is off, whatever the options below say.\") end\n    values.clear, changed = GUI:Checkbox(\"Clear my marks after each mechanic##AMclear\", values.clear ~= false)\n    if changed then store.save() end\n    if GUI:IsItemHovered() then GUI:SetTooltip(\"Clears only the marks this writer put on. A mark anyone else set is never touched.\") end\n    local preset = AM.preset()\n    GUI:Text(\"Rules of the active preset: \" .. (preset or \"not loaded yet\"))\n    GUI:Spacing()\n    values.transition, changed = GUI:Checkbox(\"P3 Transition (Intermission)##AMtransition\", values.transition == true)\n    if changed then store.save() end\n    if GUI:IsItemHovered() then GUI:SetTooltip(\"Attack 1-4 on the spreads left to right, Bind 1/2 on the stack pair, Ignore 1/2 on the other two.\") end\n    values.monitor, changed = GUI:Checkbox(\"P3 Monitors##AMmonitor\", values.monitor == true)\n    if changed then store.save() end\n    if GUI:IsItemHovered() then GUI:SetTooltip(\"Monitor players Bind 1-3, the others Attack 1-5, in the line-up of the active preset.\") end\n    GUI:Spacing()\n    values.delta, changed = GUI:Checkbox(\"P5 Delta##AMdelta\", values.delta == true)\n    if changed then store.save() end\n    if GUI:IsItemHovered() then GUI:SetTooltip(\"Marks the Distant and Near World players (Lemegeton's rule). Not for Mana.\") end\n    values.sigma, changed = GUI:Checkbox(\"P5 Sigma##AMsigma\", values.sigma == true)\n    if changed then store.save() end\n    if GUI:IsItemHovered() then GUI:SetTooltip(\"Arms, baits and World players, 30s after the debuffs (Lemegeton's rule). Not for Mana.\") end\n    values.omega, changed = GUI:Checkbox(\"P5 Omega##AMomega\", values.omega == true)\n    if changed then store.save() end\n    if GUI:IsItemHovered() then GUI:SetTooltip(\"Monitors, World players and baits for both sets (Lemegeton's rule). Not for Mana.\") end\n    GUI:Spacing()\n    GUI:TextColored(0.55, 0.55, 0.6, 1, \"No rule yet: P1 Program Loop, P1 Pantokrator, P2 Party Synergy.\")\n    GUI:Spacing()\n    GUI:Text(\"Last: \" .. tostring(AM.status))\n    if store.error then GUI:Text(\"Settings could not be saved: \" .. store.error) end\nend\n\nself.used = true\n",
