		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- [Rings] Spread and Stack (2026-11-22, the user: \"let's add that and I will check and tell you later\", about the baited/targeted rings).\n-- Slim rings on the players an attack is aimed at, so you can see where it lands and whether you are inside someone else's.\n-- P2 Party Synergy: Optimized Fire III 31535 spreads every player, radius 7, lands 247.7 (shown from the dodge at 241.4).\n-- P3 Intermission: spread 3425 (Sniper Cannon 31571, radius 6) and stack 3426 (High-powered Sniper Cannon 31572, radius 6, a pair), land 428.2.\n-- Also P6 tank auto circles and (group p3, off by default) the P3 Hello World circles. Orange = spread, green = stack, yellow = tank autos. A spread ring turns red when another player is inside it; mine is thicker. Radii from the game's AOE data.\nlocal D = data.topDraws\nif D == nil then\n    local path = GetLuaModsPath() .. [[TensorReactions\\Settings\\TOP-Draws.lua]]\n    local saved = FileExists(path) and FileLoad(path)\n    D = { path = path, values = type(saved) == \"table\" and saved or {} }\n    D.defaults = { all = true, weapons = true, p2tank = true, p5 = true, p6 = true, p1 = false, p3 = false, rings = true }\n    function D.on(group)\n        local v = D.values[group]\n        if v == nil then v = D.defaults[group] end\n        return v == true\n    end\n    data.topDraws = D\nend\n-- Immediate-draw manager (2026-11-22, the user: \"revert the timed draw changes\"): the same K.begin/K.put/K.sweep calls as the timed manager, but each put draws the\n-- shape for this frame only (addCircle / addRect / addCone / addDonut) instead of creating an engine timed shape. Shapes that followed an entity are drawn at its\n-- current position.\nlocal K = data.masadoTimed\nif K == nil or K.v ~= 2 then\n    K = { v = 2 }\n    function K.begin(prefix) end\n    function K.sweep(prefix) end\n    local function pos(id)\n        local e = id and TensorCore.mGetEntity(id)\n        return e and e.pos or nil\n    end\n    function K.put(prefix, key, drawer, kind, ...)\n        local a = { ... }\n        if kind == \"circle\" then\n            drawer:addCircle(a[1], a[2], a[3], a[4])\n        elseif kind == \"circleEnt\" then\n            local p = pos(a[1])\n            if p then drawer:addCircle(p.x, p.y, p.z, a[2]) end\n        elseif kind == \"rect\" then\n            drawer:addRect(a[1], a[2], a[3], a[4], a[5], a[6])\n        elseif kind == \"rectEnt\" then\n            local src, dst = pos(a[1]), pos(a[4])\n            if src and dst then drawer:addRect(src.x, src.y, src.z, a[2], a[3], math.atan2(dst.x - src.x, dst.z - src.z)) end\n        elseif kind == \"cone\" then\n            drawer:addCone(a[1], a[2], a[3], a[4], a[5], a[6])\n        elseif kind == \"coneEnt\" then\n            local src, dst = pos(a[1]), pos(a[4])\n            if src and dst then drawer:addCone(src.x, src.y, src.z, a[2], a[3], math.atan2(dst.x - src.x, dst.z - src.z)) end\n        elseif kind == \"donut\" then\n            drawer:addDonut(a[1], a[2], a[3], a[4], a[5])\n        end\n    end\n    data.masadoTimed = K\nend\nlocal t = TensorReactions_CurrentTimer or 0\nlocal me = TensorCore.mGetPlayer()\nK.begin(\"ring:\")\nif not D.on(\"rings\") or me == nil or me.pos == nil then\n    K.sweep(\"ring:\")\n    self.used = true\n    return\nend\nlocal R = data.topRings\nif R == nil or R.v ~= 4 then\n    R = { v = 4 }\n    R.PHASES = {\n        { from = 241.4, to = 247.9, kind = \"all\", r = 7 },\n        { from = 415.0, to = 428.4, kind = \"buff\", buff = 3425, r = 6 },\n        { from = 415.0, to = 428.4, kind = \"buff\", buff = 3426, r = 6, stack = true },\n        -- P3 Hello World (off with the \"P3\" group, which the user removed earlier): Defamation (Critical Overflow Bug) r20, Stack\n        -- (Critical Synchronization Bug) r5, rots (Critical Underflow / Performance Bug) r5, from the active debuffs.\n        { from = 440.0, to = 560.0, kind = \"buff\", buff = 3525, r = 20 }, -- Defamation always on (the user, 2026-11-22)\n        { from = 440.0, to = 560.0, kind = \"buff\", buff = 3524, r = 5, stack = true, group = \"p3\" },\n        { from = 440.0, to = 560.0, kind = \"buff\", buff = 3526, r = 5, group = \"p3\" },\n        { from = 440.0, to = 560.0, kind = \"buff\", buff = 3429, r = 5, group = \"p3\" },\n        -- P6 auto attacks of Alpha Omega (32223 splashes radius 5 around its target; 3 autos about 3s apart, near and far tank at once):\n        -- a ring on each tank so nobody else stands in it. Windows from the 25 logged pulls.\n        { from = 1171.0, to = 1177.5, kind = \"tanks\", r = 5 }, { from = 1205.0, to = 1211.5, kind = \"tanks\", r = 5 },\n        { from = 1247.0, to = 1253.5, kind = \"tanks\", r = 5 }, { from = 1281.0, to = 1287.5, kind = \"tanks\", r = 5 },\n        { from = 1318.0, to = 1324.5, kind = \"tanks\", r = 5 },\n    }\n    R.TANKS = { [19] = true, [21] = true, [32] = true, [37] = true }\n    R.auto = TensorCore.getCachedDrawer(nil, nil, 0x1500FFFF, 0xFF00D7FF, 1.5)\n    R.spread = TensorCore.getCachedDrawer(nil, nil, 0x220088FF, 0xFF0088FF, 1.5)\n    R.mine = TensorCore.getCachedDrawer(nil, nil, 0x330088FF, 0xFF00CCFF, 3)\n    R.warn = TensorCore.getCachedDrawer(nil, nil, 0x330000FF, 0xFF0000FF, 2.5)\n    R.stack = TensorCore.getCachedDrawer(nil, nil, 0x2200FF00, 0xFF00FF00, 1.5)\n    data.topRings = R\nend\nlocal active\nfor _, p in ipairs(R.PHASES) do\n    if t >= p.from and t <= p.to and (p.group == nil or D.on(p.group)) then\n        active = true\n        break\n    end\nend\nif not active then\n    K.sweep(\"ring:\")\n    self.used = true\n    return\nend\nlocal party = { me }\nfor id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\") or {}) do\n    if e and e.id ~= me.id and e.pos then party[#party + 1] = e end\nend\nlocal function alive(e) return e.hp == nil or e.hp.current == nil or e.hp.current > 0 end\nlocal meTank = R.TANKS[me.job] == true\nfor index, p in ipairs(R.PHASES) do\n    if t >= p.from and t <= p.to and (p.group == nil or D.on(p.group)) then\n        for _, e in ipairs(party) do\n            local md = data.masadoDraws\n            local defamDone = p.buff == 3525 and md and md.defamHit and Now() - md.defamHit < 6000\n            -- Defamation only while that player soaks a tower (the user, 2026-11-22: \"only draw defamations when people soaking defamation towers\"):\n            -- the live Patch's towers from [Hello] Solver (r14 bearings), soaking = within 6.5y of one, until the towers hit (start + 10.05s).\n            if p.buff == 3525 and not defamDone then\n                local hs = data.topHello\n                local soaking = false\n                for _, row in pairs(hs and hs.towers or {}) do\n                    if row.start and t >= row.start and t <= row.start + 10.1 and e.pos then\n                        for _, list in ipairs({ row.red or {}, row.blue or {} }) do\n                            for _, b in ipairs(list) do\n                                local a = math.rad(b)\n                                local tx, tz = 100 + 14 * math.sin(a), 100 - 14 * math.cos(a)\n                                if (e.pos.x - tx) ^ 2 + (e.pos.z - tz) ^ 2 < 6.5 * 6.5 then soaking = true end\n                            end\n                        end\n                    end\n                end\n                defamDone = not soaking\n            end\n            if not defamDone and e.pos and alive(e) and (p.kind == \"all\" or (p.kind == \"tanks\" and R.TANKS[e.job]) or (p.kind == \"buff\" and TensorCore.hasBuff(e.id, p.buff))) then\n                local drawer\n                if p.kind == \"tanks\" then\n                    drawer = R.auto\n                    if not meTank and e.id ~= me.id then\n                        local dx, dz = me.pos.x - e.pos.x, me.pos.z - e.pos.z\n                        if dx * dx + dz * dz < p.r * p.r then drawer = R.warn end\n                    end\n                elseif p.stack then\n                    drawer = R.stack\n                else\n                    drawer = e.id == me.id and R.mine or R.spread\n                    for _, o in ipairs(party) do\n                        if o.id ~= e.id and o.pos and alive(o) then\n                            local dx, dz = o.pos.x - e.pos.x, o.pos.z - e.pos.z\n                            if dx * dx + dz * dz < p.r * p.r then\n                                drawer = R.warn\n                                break\n                            end\n                        end\n                    end\n                end\n                -- A timed circle attached to the player: it follows them by itself, only a colour change recreates it.\n                K.put(\"ring:\", index .. \":\" .. e.id, drawer, \"circleEnt\", e.id, p.r, 0, false, true)\n            end\n        end\n    end\nend\nK.sweep(\"ring:\")\nself.used = true\n",
