						{
							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 41 then\n    cfg = {\n        version = 41,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- Mana: arrow to my Wave Cannon Kyrios spot after Pantokrator.\n            kyrArrow = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Line colour for the \"Tether\" style (the user, 2026-11-15; it used to come out white).\n            tetherColor = \"Red\",\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Tether line colours (ABGR). Every colour slot of the line drawer gets the same one: with a white outline slot the\n    -- line came out white.\n    cfg.TETHER_COLOR_NAMES = { \"Red\", \"Orange\", \"Yellow\", \"Green\", \"Cyan\", \"Blue\", \"Magenta\", \"White\" }\n    cfg.TETHER_COLORS = { Red = 0xFF0000FF, Orange = 0xFF0088FF, Yellow = 0xFF00FFFF, Green = 0xFF00FF00, Cyan = 0xFFFFFF00,\n                          Blue = 0xFFFF0000, Magenta = 0xFFFF00FF, White = 0xFFFFFFFF }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                local colors = live.TETHER_COLORS or {}\n                local color = colors[live.values.tetherColor] or 0xFF0000FF\n                live.tetherDrawers = live.tetherDrawers or {}\n                local drawer = live.tetherDrawers[color]\n                if drawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    drawer = TensorCore.getCachedDrawer(color, color, color, color, 2, 0, overlay)\n                    live.tetherDrawers[color] = drawer\n                end\n                drawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() and not (Roster.state and Roster.state()) then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        local naur = Roster.state and Roster.state()\n        if naur then\n            saved = { members = {}, jobs = {} }\n            for slot, row in pairs(naur.bySlot) do saved.members[row.key] = slot; saved.jobs[row.key] = row.job end\n        end\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P2 Party Synergy, the guide's knockback flex: each pair splits left and right by the conga. With both stack markers on one\n-- side, the stack nearer the eye swaps groups with their partner. Shapes 416-419 land at 234, stack markers 100 at 248.6.\nlocal marker = eventArgs.markerID\nlocal t = TensorReactions_CurrentTimer\nlocal s = data.topSynergyFlex\nif marker >= 416 and marker <= 419 and (s == nil or Now() - s.at > 5000) then\n    -- The shapes all land together, so one more than 5s after the last is a new pull. The timer reads the same each pull.\n    s = { at = Now(), shapes = {}, stacks = {} }\n    data.topSynergyFlex = s\nend\nif s == nil then\n    self.used = true\n    return\nend\n\nlocal function log(text)\n    d(\"[Synergy] \" .. text)\n    TensorCore.timelineLogToFile(\"[Synergy] \" .. text .. \"\\n\")\nend\n\nif marker >= 416 and marker <= 419 then\n    s.shapes[eventArgs.entityID] = marker\nelseif marker == 100 and not s.done then\n    s.stacks[#s.stacks + 1] = eventArgs.entityID\n    local me = TensorCore.mGetPlayer()\n    if #s.stacks == 2 and me then\n        s.done = true\n        local Roster = NAUR_Roster or (AnyoneCore and AnyoneCore.Roster)\n        local view = Roster and Roster.current() ~= nil and cfg.rosterView(Roster, me) or nil\n        local glitch = TensorCore.hasBuff(me.id, 3427) and \"mid\" or (TensorCore.hasBuff(me.id, 3428) and \"far\" or nil)\n        if view == nil then\n            log(\"flex: no Party Roster\")\n        elseif glitch == nil then\n            log(\"flex: no Mid or Remote Glitch on me\")\n        else\n            local CONGA = { H1 = 1, R1 = 2, M1 = 3, T1 = 4, T2 = 5, M2 = 6, R2 = 7, H2 = 8 }\n            -- Each shape's players, left first.\n            local holders = {}\n            for id, shape in pairs(s.shapes) do\n                holders[shape] = holders[shape] or {}\n                table.insert(holders[shape], id)\n            end\n            local function rank(id) return CONGA[view.slotOf(id)] or 99 end\n            local count = 0\n            for _, ids in pairs(holders) do\n                table.sort(ids, function(a, b) return rank(a) < rank(b) end)\n                count = count + #ids\n            end\n            -- Mana uses Elemental's groups, swap rule and stack flex; only its Remote right column order differs.\n            local mana = cfg.values.mana and not cfg.values.elemental\n            local elemental = cfg.values.elemental or mana\n            local ldpu = cfg.values.ldpu\n            local function sideOf(id)\n                local ids = holders[s.shapes[id]]\n                if ids == nil then return nil end\n                if (elemental or ldpu) and #ids == 2 then\n                    -- Elemental: light party 1 (H1 MT D1 D3) left, 2 right; two of a shape in one group sends the lower across.\n                    -- LPDU: the same columns lined up T H M R north to south; the southern one adjusts across.\n                    local G1 = { H1 = true, T1 = true, M1 = true, R1 = true }\n                    local ORDER = elemental and { H1 = 1, T1 = 2, M1 = 3, R1 = 4, H2 = 1, T2 = 2, M2 = 3, R2 = 4 }\n                        or { T1 = 1, H1 = 2, M1 = 3, R1 = 4, T2 = 1, H2 = 2, M2 = 3, R2 = 4 }\n                    local other = ids[1] == id and ids[2] or ids[1]\n                    local a, b = view.slotOf(id), view.slotOf(other)\n                    local mine = G1[a] and \"left\" or \"right\"\n                    if mine ~= (G1[b] and \"left\" or \"right\") or (ORDER[a] or 9) < (ORDER[b] or 9) then return mine end\n                    return mine == \"left\" and \"right\" or \"left\"\n                end\n                return ids[1] == id and \"left\" or \"right\"\n            end\n            local one, two = s.stacks[1], s.stacks[2]\n            local myShape = s.shapes[me.id]\n            if count ~= 8 or sideOf(one) == nil or sideOf(two) == nil or myShape == nil then\n                log(string.format(\"flex: %d of 8 shapes seen, can't tell\", count))\n            else\n                -- Order from the eye, from the spread spots: 419 cross, 418 square, 416 circle, 417 triangle.\n                local NEAR = { [419] = 1, [418] = 2, [416] = 3, [417] = 4 }\n                if elemental then\n                    -- Elemental: ○ × ▽ □ from the eye; on Remote the right group swaps ○ and □.\n                    NEAR = { [416] = 1, [419] = 2, [417] = 3, [418] = 4 }\n                    local farRight = mana and { [418] = 1, [417] = 2, [419] = 3, [416] = 4 } or { [418] = 1, [419] = 2, [417] = 3, [416] = 4 }\n                    NEAR = { left = NEAR, right = glitch == \"far\" and farRight or NEAR }\n                elseif ldpu then\n                    -- LPDU: B-P-O-G from the eye on the left; on Remote the right column is G-P-O-B (the user, 2026-11-10).\n                    NEAR = { left = NEAR, right = glitch == \"far\" and { [417] = 1, [418] = 2, [416] = 3, [419] = 4 } or NEAR }\n                elseif glitch == \"far\" then\n                    NEAR = { left = NEAR, right = { [417] = 1, [418] = 2, [416] = 3, [419] = 4 } }\n                else\n                    NEAR = { left = NEAR, right = NEAR }\n                end\n                local flexShape\n                local side = sideOf(one)\n                if side == sideOf(two) then\n                    local a, b = s.shapes[one], s.shapes[two]\n                    -- Which stack flexes. \"Strat default\": NA the one nearer the eye; Elemental (and Mana) the one further from the\n                    -- eye; LPDU \"the South-most stack from the lineup\" (the B-P-O-G line, eye north), also the further one. The user\n                    -- can force either one with \"Which stack flexes\" (2026-11-10).\n                    local rule = cfg.values.synFlexRule\n                    local further = elemental or ldpu\n                    if rule == \"Closest to eye\" then further = false elseif rule == \"Furthest from eye\" then further = true end\n                    if further then\n                        flexShape = NEAR[side][a] > NEAR[side][b] and a or b\n                    else\n                        flexShape = NEAR[side][a] < NEAR[side][b] and a or b\n                    end\n                end\n                local mySide = sideOf(me.id)\n                local pair = holders[myShape]\n                local partner = pair[1] == me.id and pair[2] or pair[1]\n                s.group = mySide\n                if flexShape == myShape then s.group = mySide == \"left\" and \"right\" or \"left\" end\n                local text\n                if flexShape == myShape then\n                    text = string.format(\"FLEX with %s: go %s\", tostring(view.slotOf(partner)), mySide == \"left\" and \"right\" or \"left\")\n                else\n                    text = \"No flex: stay \" .. mySide\n                end\n                log(string.format(\"%.1f stacks %s %s, %s glitch, flex shape %s: %s\", t, tostring(view.slotOf(one)), tostring(view.slotOf(two)), glitch, tostring(flexShape), text))\n                s.text = text\n                if cfg.values.synFlex and cfg.values.calloutOn ~= false then\n                    TensorCore.addAlertText(4000, text, 1.8, flexShape == myShape and 3 or 1, cfg.values.tts)\n                end\n            end\n        end\n    end\nend\nself.used = true\n",
							name = "Record Synergy Flex",
							uuid = "ce94e14f-7354-6c9d-89ff-a979fc5d78c4",
							version = 2.1,
						},
