							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 41 then\n    cfg = {\n        version = 41,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- Mana: arrow to my Wave Cannon Kyrios spot after Pantokrator.\n            kyrArrow = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Line colour for the \"Tether\" style (the user, 2026-11-15; it used to come out white).\n            tetherColor = \"Red\",\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Tether line colours (ABGR). Every colour slot of the line drawer gets the same one: with a white outline slot the\n    -- line came out white.\n    cfg.TETHER_COLOR_NAMES = { \"Red\", \"Orange\", \"Yellow\", \"Green\", \"Cyan\", \"Blue\", \"Magenta\", \"White\" }\n    cfg.TETHER_COLORS = { Red = 0xFF0000FF, Orange = 0xFF0088FF, Yellow = 0xFF00FFFF, Green = 0xFF00FF00, Cyan = 0xFFFFFF00,\n                          Blue = 0xFFFF0000, Magenta = 0xFFFF00FF, White = 0xFFFFFFFF }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                local colors = live.TETHER_COLORS or {}\n                local color = colors[live.values.tetherColor] or 0xFF0000FF\n                live.tetherDrawers = live.tetherDrawers or {}\n                local drawer = live.tetherDrawers[color]\n                if drawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    drawer = TensorCore.getCachedDrawer(color, color, color, color, 2, 0, overlay)\n                    live.tetherDrawers[color] = drawer\n                end\n                drawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() and not (Roster.state and Roster.state()) then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        local naur = Roster.state and Roster.state()\n        if naur then\n            saved = { members = {}, jobs = {} }\n            for slot, row in pairs(naur.bySlot) do saved.members[row.key] = slot; saved.jobs[row.key] = row.job end\n        end\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P2 Limitless Synergy, tanks (P2 deck slides 30-38): an arrow through the tether, the shielded Omega M and Beyond Defense.\n-- MT (T1) takes the tether counter-clockwise from North, OT (T2) the one clockwise from North. Bring it toward the add, then point it\n-- clockwise at the wall \"4-5 notches\" from the add (30 degrees, the average of the user's tanks in 4 logged pulls). After the busters\n-- both sit max melee in front of the shielded Omega M. Beyond Defense's target (Twice-come Ruin, 2534) rotates around the hitbox\n-- away from the party; the other tank goes into the party in the middle for Pile Pitch.\nlocal values = cfg.values\nlocal t = TensorReactions_CurrentTimer\nlocal REV = \"2026-11-22-lines\"\nlocal s = data.topLimitlessTank\nif s == nil or s.rev ~= REV then\n    s = { rev = REV, warned = {} }\n    data.topLimitlessTank = s\n    s.TETHERS_FROM, s.WALL_FROM, s.BUSTER, s.DEFENSE, s.RUIN_BY, s.PITCH = 287.4, 293.0, 295.95, 306.95, 307.9, 310.0\n    s.GRAB_R, s.WALL_R, s.NOTCHES, s.MELEE = 14, 19, 30, 2\n    s.RUIN = 2534\n    s.drawArrow = cfg.styledArrow(\"stLim\", TensorCore.getCachedDrawer(0xFF00FFFF, 0xFF0088FF, 0xFF0000FF, 0xFFFFFFFF, 2))\n    s.drawMine = TensorCore.getCachedDrawer(nil, nil, 0x6600FF00, 0xFF00FF00, 2)\n    s.drawNext = TensorCore.getCachedDrawer(nil, nil, 0x550000FF, 0xFF0000FF, 2)\n\n    function s.warnOnce(key, text)\n        if not s.warned[key] then\n            s.warned[key] = true\n            d(\"[Limitless] \" .. text)\n            TensorCore.timelineLogToFile(\"[Limitless] \" .. text .. \"\\n\")\n        end\n    end\n\n    function s.at(bearing, radius)\n        local a = math.rad(bearing)\n        return { x = 100 + radius * math.sin(a), z = 100 - radius * math.cos(a) }\n    end\n\n    -- Counter-clockwise from North is the west half (180-360), clockwise the east half.\n    -- Elemental: MT takes the north tether, ST the south one.\n    function s.myTether(tethers, slot)\n        for _, c in ipairs(tethers) do\n            local first\n            if values.elemental then\n                first = c.bearing > 270 or c.bearing < 90\n            else\n                first = c.bearing > 180 and c.bearing < 360\n            end\n            if (slot == \"T1\" and first) or (slot == \"T2\" and not first) then return c end\n        end\n    end\n\n    -- Elemental (ffxiv.tuufless.com/elemental/top/02_omega_mf, images 02, 04, 05, FAQ): tethers 24.6 degrees clockwise (the\n    -- FAQ's tangent at r=20 from the clone at r=22); after the busters both tanks just outside the boss's hitbox towards the\n    -- shield clone, MT clockwise and ST counter-clockwise of it; the Beyond Defense target runs round to the far side, the other\n    -- stacks with the party in the middle.\n    s.ELEMENTAL_NOTCHES, s.ELEMENTAL_SPREAD = 24.6, 37\n    function s.elementalAround(shield, slot, hit)\n        local e = shield and TensorCore.mGetEntity(shield)\n        if e == nil or e.pos == nil then return nil end\n        local b = math.deg(math.atan2(e.pos.x - 100, 100 - e.pos.z))\n        local r = 6\n        for _, boss in pairs(TensorCore.entityList(\"contentid=7633\")) do\n            if boss.pos and boss.hitradius and (boss.pos.x - 100) ^ 2 + (boss.pos.z - 100) ^ 2 < 4 then r = boss.hitradius end\n        end\n        local bearing = hit and b + 180 or b + (slot == \"T1\" and s.ELEMENTAL_SPREAD or -s.ELEMENTAL_SPREAD)\n        return s.at(bearing, r + 1)\n    end\n\n    -- Max melee in front of the shielded Omega M (it faces the middle), or that far round its side for the Beyond Defense target.\n    function s.aroundShield(shield, turn, me)\n        local e = shield and TensorCore.mGetEntity(shield)\n        if e == nil or e.pos == nil then return nil end\n        local reach = (e.hitradius or 5) + s.MELEE\n        s.warnOnce(\"hitbox\", string.format(\"shielded Omega M at (%.1f,%.1f) facing %.0f, hitbox %.1f\", e.pos.x, e.pos.z,\n            math.deg(e.pos.h), e.hitradius or -1))\n        local h = e.pos.h\n        if turn then\n            -- Away from the party: round to the side I'm already on.\n            local fx, fz = math.sin(h), math.cos(h)\n            local side = (fx * (me.pos.z - e.pos.z) - fz * (me.pos.x - e.pos.x)) >= 0 and -1 or 1\n            h = h + side * math.pi / 2\n        end\n        return { x = e.pos.x + math.sin(h) * reach, z = e.pos.z + math.cos(h) * reach }\n    end\n\n    -- [2026-11-22] Wall-spot chooser (the user: \"consider the Sagittarius arrow from the entity too, and also not cleaving the non-tank members\").\n    -- Sagittarius Arrow 31539: the shielded Omega M's line, width 10, length 100, aimed at the centre on the channel and turning up to\n    -- ~0.35 rad before it fires (22 pulls), so its live heading is used (half width 5 + 1y margin). Bladedance (damage 32629) goes\n    -- from my tether clone along its heading to its tank and hit five non-tanks standing on that line (11/22 11:17), so no non-tank\n    -- may stand within 3y of the line clone -> my spot.\n    s.OFFSETS, s.ARROW_HALF, s.CLEAVE_HALF = { 30, 36, 42, 48, 24.6, 18, 12 }, 6, 3\n\n    function s.alongPerp(x0, z0, hx, hz, px, pz)\n        local dx, dz = px - x0, pz - z0\n        return dx * hx + dz * hz, math.abs(dx * hz - dz * hx)\n    end\n\n    function s.inArrow(rec, sp)\n        local a = rec.arrow\n        if a == nil then return false end\n        -- The arrow's own live heading once it can be read (it turns toward its target as it casts); until then +-0.2 rad around the recorded one.\n        local e = a.id and TensorCore.mGetEntity(a.id)\n        local headings = {}\n        if e and e.pos and e.pos.h then\n            headings[1] = e.pos.h\n        else\n            for k = -2, 2 do headings[#headings + 1] = a.h + k * 0.1 end\n        end\n        for _, h in ipairs(headings) do\n            local along, perp = s.alongPerp(a.x, a.z, math.sin(h), math.cos(h), sp.x, sp.z)\n            if along > 0 and perp < s.ARROW_HALF then return true end\n        end\n        return false\n    end\n\n    function s.nonTanks(view)\n        local list = {}\n        for _, slot in ipairs({ \"H1\", \"H2\", \"M1\", \"M2\", \"R1\", \"R2\" }) do\n            local id = view.idOf and view.idOf(slot)\n            local e = id and TensorCore.mGetEntity(id)\n            if e and e.pos and e.hp and e.hp.current > 0 then list[#list + 1] = { slot = slot, x = e.pos.x, z = e.pos.z } end\n        end\n        return list\n    end\n\n    function s.cleaves(clone, sp, others)\n        local hx, hz = sp.x - clone.x, sp.z - clone.z\n        local len = math.sqrt(hx * hx + hz * hz)\n        local hit = {}\n        if len < 1 then return hit end\n        hx, hz = hx / len, hz / len\n        for _, o in ipairs(others) do\n            local along, perp = s.alongPerp(clone.x, clone.z, hx, hz, o.x, o.z)\n            if along > 0 and perp < s.CLEAVE_HALF then hit[#hit + 1] = o.slot end\n        end\n        return hit\n    end\n\n    -- Returns the wall spot and its offset in degrees. The usual offset first, then further round clockwise (\"if the line AOE is on top of where\n    -- the tanks have to go, they should go past it\", P2 deck slide 32), then the shorter ones; if none is clean at the usual radius the same\n    -- list is tried again right at the wall (\"as close to the wall as possible\" for the parallel case, slide 35).\n    function s.pickWall(rec, mine, view)\n        local base = values.elemental and s.ELEMENTAL_NOTCHES or s.NOTCHES\n        local e = mine.id and TensorCore.mGetEntity(mine.id)\n        local clone = (e and e.pos) and { x = e.pos.x, z = e.pos.z } or s.at(mine.bearing, 22)\n        local others = s.nonTanks(view)\n        local list = { base }\n        for _, off in ipairs(s.OFFSETS) do\n            if off ~= base then list[#list + 1] = off end\n        end\n        local function clean(off, radius)\n            local sp = s.at(mine.bearing + off, radius)\n            local arrow = s.inArrow(rec, sp)\n            local hit = s.cleaves(clone, sp, others)\n            return (not arrow) and #hit == 0, sp, arrow, hit\n        end\n        if s.curOff then\n            local ok, sp = clean(s.curOff, s.curRadius or s.WALL_R)\n            if ok then\n                s.cleave = { cx = clone.x, cz = clone.z, sp = sp }\n                return sp, s.curOff\n            end\n        end\n        local firstWhy\n        for _, radius in ipairs({ s.WALL_R, 21 }) do\n            for _, off in ipairs(list) do\n                local ok, sp, arrow, hit = clean(off, radius)\n                if off == base and radius == s.WALL_R then firstWhy = { arrow = arrow, hit = hit } end\n                if ok then\n                    s.curOff, s.curRadius = off, radius\n                    s.cleave = { cx = clone.x, cz = clone.z, sp = sp }\n                    if off ~= base or radius ~= s.WALL_R then\n                        s.warnOnce(\"pick\" .. off .. \"r\" .. radius, string.format(\"wall spot %.1f deg at r%d instead of %.1f (%s%s)\", off, radius, base,\n                            firstWhy.arrow and \"arrow line \" or \"\", #firstWhy.hit > 0 and (\"would cleave \" .. table.concat(firstWhy.hit, \",\")) or \"\"))\n                    end\n                    return sp, off\n                end\n            end\n        end\n        local sp = s.at(mine.bearing + base, s.WALL_R)\n        s.curOff, s.curRadius = nil, nil\n        s.cleave = { cx = clone.x, cz = clone.z, sp = sp }\n        s.warnOnce(\"nopick\", \"no clean wall spot (arrow line and/or a non-tank on the cleave), keeping \" .. base .. \" deg\")\n        return sp, base\n    end\nend\n\n-- Immediate-draw manager (2026-11-22, the user: \"revert the timed draw changes\"): the same LK.begin/LK.put/LK.sweep calls as the timed manager, but each put draws the\n-- shape for this frame only (addCircle / addRect / addCone / addDonut) instead of creating an engine timed shape. Shapes that followed an entity are drawn at its\n-- current position.\nlocal LK = data.masadoTimed\nif LK == nil or LK.v ~= 2 then\n    LK = { v = 2 }\n    function LK.begin(prefix) end\n    function LK.sweep(prefix) end\n    local function pos(id)\n        local e = id and TensorCore.mGetEntity(id)\n        return e and e.pos or nil\n    end\n    function LK.put(prefix, key, drawer, kind, ...)\n        local a = { ... }\n        if kind == \"circle\" then\n            drawer:addCircle(a[1], a[2], a[3], a[4])\n        elseif kind == \"circleEnt\" then\n            local p = pos(a[1])\n            if p then drawer:addCircle(p.x, p.y, p.z, a[2]) end\n        elseif kind == \"rect\" then\n            drawer:addRect(a[1], a[2], a[3], a[4], a[5], a[6])\n        elseif kind == \"rectEnt\" then\n            local src, dst = pos(a[1]), pos(a[4])\n            if src and dst then drawer:addRect(src.x, src.y, src.z, a[2], a[3], math.atan2(dst.x - src.x, dst.z - src.z)) end\n        elseif kind == \"cone\" then\n            drawer:addCone(a[1], a[2], a[3], a[4], a[5], a[6])\n        elseif kind == \"coneEnt\" then\n            local src, dst = pos(a[1]), pos(a[4])\n            if src and dst then drawer:addCone(src.x, src.y, src.z, a[2], a[3], math.atan2(dst.x - src.x, dst.z - src.z)) end\n        elseif kind == \"donut\" then\n            drawer:addDonut(a[1], a[2], a[3], a[4], a[5])\n        end\n    end\n    data.masadoTimed = LK\nend\nLK.begin(\"lim:\")\nlocal me = TensorCore.mGetPlayer()\nlocal rec = data.topLimitless\nif not values.limTank or me == nil or me.pos == nil or me.hp.current <= 0 or t < s.TETHERS_FROM or t >= s.PITCH then\n    self.used = true\n    return\nend\nif rec == nil or Now() - rec.at > 40000 then\n    self.used = true\n    return\nend\nif s.seen ~= rec.at then\n    s.seen, s.warned, s.curOff, s.curRadius, s.cleave = rec.at, {}, nil, nil, nil\nend\nlocal Roster = NAUR_Roster or (AnyoneCore and AnyoneCore.Roster)\nlocal view = Roster and Roster.current() ~= nil and cfg.rosterView(Roster, me) or nil\nlocal slot = view and view.mySlot()\nif slot ~= \"T1\" and slot ~= \"T2\" then\n    self.used = true\n    return\nend\nlocal mine = s.myTether(rec.tethers, slot)\n-- Live tether (2026-11-23): Limitless clones tether players with type 84 (clone -> player). If a clone's tether is on me, that clone is mine,\n-- whatever the bearing rule says (a swap or a misgrab), so the wall spot and the cleave line follow the tether I really hold.\nfor source, list in pairs(Argus.getCurrentTethers() or {}) do\n    for _, th in ipairs(list) do\n        if th.type == 84 and th.targetid == me.id then\n            for _, c in ipairs(rec.tethers) do\n                if c.id == source and c ~= mine then\n                    s.warnOnce(\"live\" .. source, string.format(\"%s: holding the tether of the clone at %.0f, not the planned one\", slot, c.bearing))\n                    mine = c\n                end\n            end\n        end\n    end\nend\nlocal spot, nextSpot\nif t < s.BUSTER then\n    if mine == nil then\n        s.warnOnce(\"tether\", string.format(\"%s: my tether clone wasn't seen (%d recorded)\", slot, #rec.tethers))\n    else\n        local wall, off = s.pickWall(rec, mine, view)\n        s.warnOnce(\"plan\", string.format(\"%s: add at %.0f, wall spot at %.0f\", slot, mine.bearing, (mine.bearing + off) % 360))\n        if t < s.WALL_FROM then\n            spot, nextSpot = s.at(mine.bearing, s.GRAB_R), wall\n        else\n            spot, nextSpot = wall, values.elemental and s.elementalAround(rec.shield, slot, false) or s.aroundShield(rec.shield, false, me)\n        end\n    end\nelseif values.elemental then\n    local hit = t >= s.DEFENSE and TensorCore.hasBuff(me.id, s.RUIN)\n    if t >= s.RUIN_BY and not hit then\n        spot = { x = 100, z = 100 }\n    else\n        spot = s.elementalAround(rec.shield, slot, hit)\n    end\n    if spot == nil then s.warnOnce(\"shield\", \"the shielded Omega M wasn't seen\") end\nelseif t < s.DEFENSE then\n    spot = s.aroundShield(rec.shield, false, me)\n    if spot == nil then s.warnOnce(\"shield\", \"the shielded Omega M wasn't seen\") end\nelse\n    if TensorCore.hasBuff(me.id, s.RUIN) then\n        spot = s.aroundShield(rec.shield, true, me)\n    elseif t < s.RUIN_BY then\n        -- Twice-come Ruin lands about 0.7s after Beyond Defense: hold until it would have.\n        spot = s.aroundShield(rec.shield, false, me)\n    else\n        spot = { x = 100, z = 100 }\n    end\nend\nif spot == nil then\n    self.used = true\n    return\nend\nlocal y = me.pos.y\ns.drawMine:addCircle(spot.x, y, spot.z, 0.8)\nif s.cleave and t < s.BUSTER + 0.2 then\n    -- my tether clone's Bladedance line: keep non-tanks off it\n    local c = s.cleave\n    if s.drawCleave == nil then s.drawCleave = TensorCore.getCachedDrawer(0x00000000, 0x00000000, 0x1A0000FF, 0xCC0000FF, 1.5) end\n    -- a timed rect, moved only when the spot changes (the user, 2026-11-22: \"make everything timed draw if possible\")\n    local hd = math.floor(TensorCore.getHeadingToTarget2(c.cx, y, c.cz, c.sp.x, y, c.sp.z) / 0.02 + 0.5) * 0.02\n    LK.put(\"lim:\", \"cleave\", s.drawCleave, \"rect\", c.cx, y, c.cz, 100, 2 * s.CLEAVE_HALF, hd, 0, nil, true)\nelse\n    LK.sweep(\"lim:\")\nend\nif nextSpot then s.drawNext:addCircle(nextSpot.x, y, nextSpot.z, 0.8) end\nlocal dx, dz = spot.x - me.pos.x, spot.z - me.pos.z\nlocal dist = math.sqrt(dx * dx + dz * dz)\nif dist > 0.5 then\n    -- Sized like the standard guide arrow, except it keeps pointing up close.\n    local scale = math.min(1, dist / 15)\n    local near = math.min(1, dist / 3)\n    local tipLength = math.min(math.max(2, 3 * scale), dist * 2 / 3)\n    s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spot.x, y, spot.z),\n        dist - tipLength, math.max(0.5, scale) * near, tipLength, math.max(1.5, 3 * scale) * near,\n        false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\nend\nself.used = true\n",
							name = "Draw Tank Tether Arrow",
							uuid = "ba6cca73-e553-5b3c-a1db-964bf327a145",
							version = 2.1,
						},
					},
				},
