							aType = "Lua",
							actionLua = "-- Colossal Blow 31566 starting: the 1st hands cast at 424.47, the 2nd at 427.01. The first cast settles which set is which.\nlocal s = data.topInter\nif s == nil then\n    s = {}\n    data.topInter = s\nend\nlocal e = TensorCore.mGetEntity(eventArgs.entityID)\nif s.castBase == nil and e and e.pos then\n    local bearing = math.deg(math.atan2(e.pos.x - 100, 100 - e.pos.z)) % 360\n    s.castBase = math.floor(bearing / 60 + 0.5) % 2 == 0 and 0 or 60\n    if s.firstBase ~= nil and s.firstBase ~= s.castBase then\n        local text = string.format(\"spawn order said base %d, the cast says %d\", s.firstBase, s.castBase)\n        d(\"[Intermission] \" .. text)\n        TensorCore.timelineLogToFile(\"[Intermission] \" .. text .. \"\\n\")\n    end\n    s.firstBase = s.castBase\nend\nself.used = true\n",
