							actionLua = "local AM = data.topAM\nif AM == nil then self.used = true return end\nlocal v = AM.store.values\nlocal enabled = v.enabled == true and v.transition == true\n-- Place the marks until the spreads and stacks resolve (resolve 428.3 + 2.7), then clear the ones we put on.\nif enabled and v.clear ~= false and (TensorReactions_CurrentTimer or 0) >= 431 then\n    local queue = AM.snapshots[\"transition\"]\n    if queue then\n        local ids = {}\n        for _, a in ipairs(queue) do ids[#ids + 1] = a.id end\n        AM.clearTick(\"transition\", ids)\n    end\nelse\n    AM.tick(\"transition\", enabled and AM.snapshot(\"transition\", AM.buildTransition) or nil, enabled)\nend\nself.used = true\n",
