	[93] = 
	{
		
		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- 31595: left (west) side safe. 31596: right (east) side safe.\nlocal s = data.topMonitor\nif s == nil then\n    s = {}\n    data.topMonitor = s\nend\ns.cast = eventArgs.spellID\nself.used = true\n",
							conditions = 
							{
								
								{
									"fae8a21a-7039-9ce1-85fe-8d4ccfeb937f",
									true,
								},
							},
							name = "Record Omega Side",
							uuid = "4fb9202d-e8a1-12ce-a575-3caa4fbbe2cc",
							version = 2.1,
						},
					},
				},
				conditions = 
				{
					
					{
						data = 
						{
							category = "Event",
							dequeueIfLuaFalse = true,
							eventArgOptionType = 3,
							eventArgType = 2,
							name = "Oversampled Wave Cannon",
							spellIDList = 
							{
								31595,
								31596,
							},
							uuid = "fae8a21a-7039-9ce1-85fe-8d4ccfeb937f",
							version = 3,
						},
					},
				},
				eventType = 3,
				loop = true,
				mechanicTime = 571.4,
				name = "[Monitor] Side",
				timeRange = true,
				timelineIndex = 93,
				timerEndOffset = 0.60000002384186,
				timerStartOffset = -12,
				uuid = "83b98cf1-3c26-cee0-be0e-841c3d07b88a",
				version = 2,
			},
		},
		
		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 41 then\n    cfg = {\n        version = 41,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- Mana: arrow to my Wave Cannon Kyrios spot after Pantokrator.\n            kyrArrow = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Line colour for the \"Tether\" style (the user, 2026-11-15; it used to come out white).\n            tetherColor = \"Red\",\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Tether line colours (ABGR). Every colour slot of the line drawer gets the same one: with a white outline slot the\n    -- line came out white.\n    cfg.TETHER_COLOR_NAMES = { \"Red\", \"Orange\", \"Yellow\", \"Green\", \"Cyan\", \"Blue\", \"Magenta\", \"White\" }\n    cfg.TETHER_COLORS = { Red = 0xFF0000FF, Orange = 0xFF0088FF, Yellow = 0xFF00FFFF, Green = 0xFF00FF00, Cyan = 0xFFFFFF00,\n                          Blue = 0xFFFF0000, Magenta = 0xFFFF00FF, White = 0xFFFFFFFF }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                local colors = live.TETHER_COLORS or {}\n                local color = colors[live.values.tetherColor] or 0xFF0000FF\n                live.tetherDrawers = live.tetherDrawers or {}\n                local drawer = live.tetherDrawers[color]\n                if drawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    drawer = TensorCore.getCachedDrawer(color, color, color, color, 2, 0, overlay)\n                    live.tetherDrawers[color] = drawer\n                end\n                drawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() and not (Roster.state and Roster.state()) then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        local naur = Roster.state and Roster.state()\n        if naur then\n            saved = { members = {}, jobs = {} }\n            for slot, row in pairs(naur.bySlot) do saved.members[row.key] = slot; saved.jobs[row.key] = row.job end\n        end\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P3 Oversampled Wave Cannon: an arrow and ring to the spot for my sign marker, from the guide's Monitors slides.\nlocal values = cfg.values\nlocal t = TensorReactions_CurrentTimer\nlocal s = data.topMonitor\n-- A new pull: the timer drops a lot or frames stopped. Timeline syncs can step back a second or more mid-mechanic.\nif s == nil or (s.lastTime and (t < s.lastTime - 5 or Now() - (s.lastClock or Now()) > 5000)) then\n    s = {}\n    data.topMonitor = s\nend\ns.lastTime = t\ns.lastClock = Now()\nif not values.monArrow and not values.monRing and not values.monFacing then\n    self.used = true\n    return\nend\n\nif not s.initialized then\n    s.initialized = true\n    s.warned = {}\n    -- The \"Left-Side Safe\" diagram, for cast 31595. \"Right-Side Safe\", for cast 31596, mirrors it across x=100.\n    -- Sign markers: 1-5 are Attack 1-5, 6-8 are Bind 1-3 (the guide's Monitors 1-3).\n    s.NAME = { \"Attack 1\", \"Attack 2\", \"Attack 3\", \"Attack 4\", \"Attack 5\", \"Bind 1\", \"Bind 2\", \"Bind 3\" }\n    s.SPOTS = {\n        { x = 97.3, z = 85.0 }, { x = 90.8, z = 89.8 }, { x = 83.4, z = 96.5 }, { x = 83.6, z = 105.8 }, { x = 98.0, z = 116.7 },\n        -- Where the monitors really stood (the user, 2026-11-22, replay 15:17, cast 31596 mirrored into this frame): Bind 1 on the outer west edge in the\n        -- north half, Bind 2 east in the south half, Bind 3 south-west. Was (110,91.8) (110,107.2) (88.5,110.5).\n        { x = 83.2, z = 93.5 }, { x = 109.7, z = 108.3 }, { x = 90.5, z = 111.0 },\n    }\n    s.BIND_3 = 8\n    -- Elemental (ffxiv.tuufless.com/elemental/top/03_omega_reconfigured, images monitors_02a/02b, averaged), in the same 31595\n    -- frame: the 3 monitor players together on one side, Players 1, 2, 4, 5 near the centre line and Player 3 at the far wall.\n    s.SPOTS_ELEMENTAL = {\n        { x = 98.6, z = 86.3 }, { x = 101.6, z = 101.2 }, { x = 112.8, z = 101.3 }, { x = 97.8, z = 110.3 }, { x = 97.8, z = 118.7 },\n        { x = 91.2, z = 87.4 }, { x = 85.6, z = 95.6 }, { x = 85.6, z = 103.5 },\n    }\n    -- Elemental line-up, north to south.\n    s.ELEMENTAL_LINE = { \"H1\", \"H2\", \"T1\", \"T2\", \"M1\", \"M2\", \"R1\", \"R2\" }\n    -- LPDU (\"Light PF monitors\" toolbox 736282987145761, step 6, measured and mirrored into the 31595 frame): M1 on the north\n    -- edge of the NW waymark, M2 the south edge of NE, M3 the north edge of SE; N1 north, N2-3 west max melee, N4 south near\n    -- the boss, N5 south at the wall. Line-up H>T>M>R from north, as Elemental's. Aims as Elemental's.\n    -- Mana (lodestone blog 5536808): Elemental's spots and aims, with the \"TDH\" line MT ST D1 D2 D3 D4 H1 H2 north to south.\n    s.MANA_LINE = { \"T1\", \"T2\", \"M1\", \"M2\", \"R1\", \"R2\", \"H1\", \"H2\" }\n    -- LPDU line-up north to south (the LPDU draws' conga).\n    s.LPDU_LINE = { \"R1\", \"M1\", \"T1\", \"H1\", \"H2\", \"T2\", \"M2\", \"R2\" }\n    s.SPOTS_LDPU = {\n        { x = 98.5, z = 83.3 }, { x = 87.2, z = 95.5 }, { x = 87, z = 104.7 }, { x = 94.3, z = 110.7 }, { x = 98.3, z = 117.7 },\n        { x = 90.5, z = 87.7 }, { x = 110.2, z = 91.5 }, { x = 110.1, z = 108.8 },\n    }\n    s.CAST_BY, s.MARKER_BY = 563, 566\n    s.drawArrow = cfg.styledArrow(\"stMon\", TensorCore.getCachedDrawer(0xFF00FFFF, 0xFF0088FF, 0xFF0000FF, 0xFFFFFFFF, 2))\n    s.drawRing = TensorCore.getCachedDrawer(nil, nil, 0x6600FF00, 0xFF00FF00, 2)\n    s.drawLine = TensorCore.getCachedDrawer(nil, nil, 0xFF00FFFF, 0xFF00FFFF, 2)\n\n    function s.warnOnce(key, text)\n        if not s.warned[key] then\n            s.warned[key] = true\n            d(\"[Monitor] \" .. text)\n            TensorCore.timelineLogToFile(\"[Monitor] \" .. text .. \"\\n\")\n        end\n    end\n\n    -- No sign marker: the guide's no-markers numbering. In the HRMTTMRH conga, north to south, the 3 players with a monitor are\n    -- Monitors 1-3 and the other 5 are Players 1-5. Read once, while everyone still has their debuff, then kept for the pull.\n    s.CONGA = { \"H1\", \"R1\", \"M1\", \"T1\", \"T2\", \"M2\", \"R2\", \"H2\" }\n    s.CONGA_FROM = 562.5\n    function s.congaMarker(me, t)\n        if s.fallback or t < s.CONGA_FROM then return s.fallback end\n        local Roster = NAUR_Roster or (AnyoneCore and AnyoneCore.Roster)\n        local view = Roster and Roster.current() ~= nil and cfg.rosterView(Roster, me) or nil\n        if view == nil then\n            s.warnOnce(\"roster\", \"no sign marker and no Party Roster: can't use the conga\")\n            return nil\n        end\n        local monitors, others, mine = 0, 0, nil\n        local line = values.elemental and s.ELEMENTAL_LINE or values.ldpu and s.LPDU_LINE or values.mana and s.MANA_LINE or s.CONGA\n        for _, slot in ipairs(line) do\n            local id = view.idOf(slot)\n            if id == nil then\n                s.warnOnce(\"slot\", \"no sign marker, and the Party Roster has no \" .. slot)\n                return nil\n            end\n            local number\n            if TensorCore.hasBuff(id, 3452) or TensorCore.hasBuff(id, 3453) then\n                monitors = monitors + 1\n                number = 5 + monitors\n            else\n                others = others + 1\n                number = others\n            end\n            if id == me.id then mine = number end\n        end\n        if monitors ~= 3 or mine == nil then\n            s.warnOnce(\"count\", string.format(\"no sign marker, and the conga can't be used: %d monitor debuffs seen\", monitors))\n            return nil\n        end\n        s.fallback = mine\n        s.warnOnce(\"conga\", string.format(\"no sign marker: the conga makes me %s\", s.NAME[mine]))\n        return mine\n    end\nend\n\nlocal me = TensorCore.mGetPlayer()\nif me == nil or me.pos == nil or me.hp.current <= 0 then\n    self.used = true\n    return\nend\nif s.cast == nil then\n    if t >= s.CAST_BY then\n        s.warnOnce(\"cast\", \"no Oversampled Wave Cannon cast seen\")\n    end\n    self.used = true\n    return\nend\nlocal spots = (values.elemental or values.mana) and s.SPOTS_ELEMENTAL or values.ldpu and s.SPOTS_LDPU or s.SPOTS\nlocal marker = me.marker\nif spots[marker] ~= nil then\n    s.lastSign = marker\nelseif s.lastSign then\n    -- Signs clear as the hits land: keep the one I had rather than falling back to the conga.\n    marker = s.lastSign\nelse\n    marker = s.congaMarker(me, t)\nend\nlocal base = spots[marker]\nif base == nil then\n    if t >= s.MARKER_BY then\n        s.warnOnce(\"marker\", \"no Attack or Bind marker on me: \" .. tostring(me.marker))\n    end\n    self.used = true\n    return\nend\n\nlocal leftSafe = s.cast == 31595\nlocal spotX = leftSafe and base.x or 200 - base.x\nlocal spotZ = base.z\nif marker == s.BIND_3 and not values.elemental and not values.ldpu and not values.mana then\n    spotZ = spotZ + values.monSouth\nend\ns.warnOnce(\"spot\" .. marker, string.format(\"%s, cast %d, %s side safe, spot (%.1f,%.1f)\", s.NAME[marker], s.cast, leftSafe and \"left (west)\" or \"right (east)\", spotX, spotZ))\n\nlocal y = me.pos.y\n-- Facing line for Monitor players. Bind 1 aims north, Bind 2 south, Bind 3 at the safe side's wall.\nif values.monFacing and marker >= 6 then\n    local aim = marker == 6 and 0 or (marker == 7 and 180 or (leftSafe and 270 or 90))\n    if values.elemental or values.ldpu or values.mana then\n        -- Elemental, LPDU and Mana: Monitor 1 aims at the monitor side's wall, 2 north, 3 south.\n        aim = marker == 6 and (leftSafe and 270 or 90) or (marker == 7 and 0 or 180)\n    end\n    local facing\n    if TensorCore.hasBuff(me.id, 3452) then\n        facing = aim - 90\n    elseif TensorCore.hasBuff(me.id, 3453) then\n        facing = aim + 90\n    end\n    if facing then\n        local a = math.rad(facing)\n        s.drawLine:addLine(spotX, y, spotZ, spotX + 6 * math.sin(a), y, spotZ - 6 * math.cos(a), 3)\n    end\nend\nif values.monRing then\n    s.drawRing:addCircle(spotX, y, spotZ, 0.8)\nend\nif values.monArrow then\n    local dx, dz = spotX - me.pos.x, spotZ - me.pos.z\n    local dist = math.sqrt(dx * dx + dz * dz)\n    if dist > 0.5 then\n        -- Sized like the standard guide arrow, except it keeps pointing up close.\n        local scale = math.min(1, dist / 15)\n        local near = math.min(1, dist / 3)\n        local tipLength = math.min(math.max(2, 3 * scale), dist * 2 / 3)\n        s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spotX, y, spotZ),\n            dist - tipLength, math.max(0.5, scale) * near, tipLength, math.max(1.5, 3 * scale) * near,\n            false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n    end\nend\nself.used = true\n",
							name = "Arrow To My Spot",
