					},
				},
				eventType = 2,
				loop = true,
				mechanicTime = 571.4,
				name = "[Face] Monitor Hit",
				timeRange = true,
				timelineIndex = 93,
				timerEndOffset = 3,
				timerStartOffset = -12,
				uuid = "8a58873f-09b8-e651-bdc2-3c5e2fb6990b",
