		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- [2026-11-16] The user asked for \"a monitor P3 analyzer just like TEA's Nisi Analyzer\".\n-- The fight logs don't record sign markers or monitor debuffs, so this records them live during P3 Oversampled Wave Cannon.\n-- For every party member it records:\n--   - their Attack/Bind sign (or the conga number when there are no signs);\n--   - their monitor debuff (3452 right, 3453 left);\n--   - where they stood and which way they faced 0.3s before the hit;\n--   - whether they died or picked up new debuffs from the hit.\n-- Each player is checked against the spot for the selected preset (NA, Elemental, LPDU or Mana, the same tables as\n-- [Monitor] Arrow), and each monitor's facing against the guide's aim.\n-- Report: LuaMods\\TensorReactions\\MonitorReports\\ and the console.\nlocal HIT = 571.4\nlocal tl = TensorReactions_CurrentTimer or 0\nlocal now = Now()\nlocal s = data.topMonRec\nif not s or (s.lastT and tl < s.lastT - 5) or (s.made and now - s.made > 120000) then\n    s = { made = now, players = {}, newBuffs = {}, base = {}, done = false }\n    data.topMonRec = s\nend\ns.lastT = tl\nif s.done then self.used = true return end\n\nlocal cfg = data.topLooperSettings\nlocal values = cfg and cfg.values or {}\nlocal SPOTS = {\n    NA = { { x = 97.3, z = 85.0 }, { x = 90.8, z = 89.8 }, { x = 83.4, z = 96.5 }, { x = 83.6, z = 105.8 }, { x = 98.0, z = 116.7 },\n           { x = 110.0, z = 91.8 }, { x = 110.0, z = 107.2 }, { x = 88.5, z = 110.5 } },\n    Elemental = { { x = 98.6, z = 86.3 }, { x = 101.6, z = 101.2 }, { x = 112.8, z = 101.3 }, { x = 97.8, z = 110.3 }, { x = 97.8, z = 118.7 },\n                  { x = 91.2, z = 87.4 }, { x = 85.6, z = 95.6 }, { x = 85.6, z = 103.5 } },\n    LPDU = { { x = 98.5, z = 83.3 }, { x = 87.2, z = 95.5 }, { x = 87, z = 104.7 }, { x = 94.3, z = 110.7 }, { x = 98.3, z = 117.7 },\n             { x = 90.5, z = 87.7 }, { x = 110.2, z = 91.5 }, { x = 110.1, z = 108.8 } },\n}\nSPOTS.Mana = SPOTS.Elemental\nlocal NAME = { \"Attack 1\", \"Attack 2\", \"Attack 3\", \"Attack 4\", \"Attack 5\", \"Bind 1\", \"Bind 2\", \"Bind 3\" }\nlocal strat = values.mana and \"Mana\" or values.ldpu and \"LPDU\" or values.elemental and \"Elemental\" or \"NA\"\n-- OCE has no table in [Monitor] Arrow; it uses the NA one there too.\nlocal LINE = (values.elemental or values.ldpu) and { \"H1\", \"H2\", \"T1\", \"T2\", \"M1\", \"M2\", \"R1\", \"R2\" }\n    or values.mana and { \"T1\", \"T2\", \"M1\", \"M2\", \"R1\", \"R2\", \"H1\", \"H2\" }\n    or { \"H1\", \"R1\", \"M1\", \"T1\", \"T2\", \"M2\", \"R2\", \"H2\" }\n\nlocal party = TensorCore.getEntityGroupList(\"Party\") or {}\nlocal Roster = NAUR_Roster or (AnyoneCore and AnyoneCore.Roster)\nlocal function slotOf(id)\n    local ok, slot = pcall(function() return Roster and Roster.current() ~= nil and Roster.slotOf(id) or nil end)\n    return ok and slot or nil\nend\n\n-- Signs and monitor debuffs, read while they are up (signs clear as the hits land).\nfor _, m in pairs(party) do\n    if m and m.id then\n        local p = s.players[m.id] or { name = m.name, slot = slotOf(m.id) }\n        s.players[m.id] = p\n        if m.marker and m.marker >= 1 and m.marker <= 8 then p.sign = m.marker end\n        if TensorCore.hasBuff(m.id, 3452) then p.mon = \"right\" elseif TensorCore.hasBuff(m.id, 3453) then p.mon = \"left\" end\n        -- Debuffs already up before the hit, so only the new ones are counted afterwards.\n        if tl < HIT - 0.3 then\n            s.base[m.id] = {}\n            for _, b in pairs(m.buffs or {}) do if b.id then s.base[m.id][b.id] = true end end\n        end\n    end\nend\n\n-- Snapshot positions and facing just before the hit.\nif not s.snap and tl >= HIT - 0.3 then\n    s.snap = true\n    s.cast = data.topMonitor and data.topMonitor.cast\n    for _, m in pairs(party) do\n        local p = m and s.players[m.id]\n        if p and m.pos then\n            p.x, p.z, p.h = m.pos.x, m.pos.z, m.pos.h\n            p.alive = m.hp and (m.hp.current or 0) > 0\n        end\n    end\nend\n\n-- After the hit: deaths and new debuffs.\nif s.snap and tl >= HIT + 0.3 then\n    for _, m in pairs(party) do\n        local p = m and s.players[m.id]\n        if p then\n            if p.alive and m.hp and (m.hp.current or 0) <= 0 then p.died = true end\n            for _, b in pairs(m.buffs or {}) do\n                local base = s.base[m.id] or {}\n                if b.id and not base[b.id] and b.id ~= 3452 and b.id ~= 3453 then\n                    p.newBuffs = p.newBuffs or {}\n                    p.newBuffs[b.id] = true\n                end\n            end\n        end\n    end\nend\n\nif not (s.snap and tl >= HIT + 3) then self.used = true return end\ns.done = true\n\n-- No signs at all: the guide's conga numbering (the 3 monitors are Binds 1-3 in line order, the rest Attacks 1-5).\nlocal anySign = false\nfor _, p in pairs(s.players) do if p.sign then anySign = true end end\nlocal conga = false\nif not anySign and Roster and Roster.current() ~= nil then\n    local mons, others = 0, 0\n    for _, slot in ipairs(LINE) do\n        local id = Roster.idOf(slot)\n        local p = id and s.players[id]\n        if p then\n            if p.mon then mons = mons + 1; p.sign = 5 + mons else others = others + 1; p.sign = others end\n        end\n    end\n    conga = true\nend\n\nlocal leftSafe = s.cast == 31595\nlocal lines, errs = {}, 0\nlines[#lines + 1] = \"TOP P3 Monitor report  \" .. os.date(\"%Y-%m-%d %H:%M:%S\")\nlines[#lines + 1] = string.format(\"Preset %s, cast %s (%s side safe)%s\", strat, tostring(s.cast),\n    s.cast == nil and \"unknown\" or (leftSafe and \"left/west\" or \"right/east\"), conga and \", no signs: conga numbering\" or \"\")\nlocal function add(kind, txt)\n    if kind == \"ERR\" then errs = errs + 1 end\n    lines[#lines + 1] = string.format(\"%-4s %s\", kind, txt)\nend\nlocal monCount = 0\nfor _, p in pairs(s.players) do if p.mon then monCount = monCount + 1 end end\nif monCount ~= 3 then add(\"INFO\", monCount .. \" monitor debuffs seen (expected 3)\") end\n\nfor _, p in pairs(s.players) do\n    local who = (p.slot and (p.slot .. \" \") or \"\") .. (p.name or \"?\")\n    local sign = p.sign and NAME[p.sign] or \"no sign\"\n    local head = string.format(\"%s [%s%s]\", who, sign, p.mon and (\", monitor \" .. p.mon) or \"\")\n    if p.sign and p.mon == nil and p.sign >= 6 then add(\"ERR\", head .. \": has a Bind sign but no monitor debuff\") end\n    if p.sign and p.mon and p.sign <= 5 then add(\"ERR\", head .. \": has a monitor debuff but an Attack sign\") end\n    local base = p.sign and SPOTS[strat][p.sign]\n    if base and p.x and s.cast then\n        local sx = leftSafe and base.x or 200 - base.x\n        local sz = base.z\n        if p.sign == 8 and strat == \"NA\" then sz = sz + (values.monSouth or 0) end\n        local dist = math.sqrt((p.x - sx) ^ 2 + (p.z - sz) ^ 2)\n        local txt = string.format(\"%s: %.1fy from spot (stood %.1f,%.1f, spot %.1f,%.1f)\", head, dist, p.x, p.z, sx, sz)\n        add(dist > 3 and \"ERR\" or \"OK\", txt)\n        if p.mon and p.sign >= 6 and p.h then\n            -- Aim per [Monitor] Arrow. Facing is 90 degrees off the aim: 3452 counter-clockwise, 3453 clockwise.\n            local aim = p.sign == 6 and 0 or (p.sign == 7 and 180 or (leftSafe and 270 or 90))\n            if strat ~= \"NA\" then aim = p.sign == 6 and (leftSafe and 270 or 90) or (p.sign == 7 and 0 or 180) end\n            local want = (p.mon == \"right\" and aim - 90 or aim + 90) % 360\n            local faced = (180 - math.deg(p.h)) % 360 -- game heading 0 = south -> bearing 0 = north\n            local off = math.abs((faced - want + 180) % 360 - 180)\n            add(off > 35 and \"ERR\" or \"OK\", string.format(\"%s: faced %.0f, should face %.0f (aim %.0f), off by %.0f\", head, faced, want, aim, off))\n        end\n    elseif not p.x then\n        add(\"INFO\", head .. \": no position recorded\")\n    end\n    if p.died then add(\"ERR\", head .. \": DIED at the hit\") end\n    if p.newBuffs then\n        local ids = {}\n        for id in pairs(p.newBuffs) do ids[#ids + 1] = tostring(id) end\n        add(\"INFO\", head .. \": new debuffs/buffs after the hit: \" .. table.concat(ids, \", \"))\n    end\nend\nlines[#lines + 1] = errs == 0 and \"No Monitor mistakes.\" or (errs .. \" mistake(s).\")\nlocal txt = table.concat(lines, \"\\n\")\nd(txt)\nlocal dir = GetLuaModsPath() .. \"TensorReactions\\\\MonitorReports\\\\\"\nif not FolderExists(dir) then FolderCreate(dir) end\nlocal f = io.open(dir .. \"monitor_\" .. os.date(\"%Y%m%d_%H%M%S\") .. \".txt\", \"w\")\nif f then f:write(txt .. \"\\n\"); f:close() end\ndata.topMonLastReport = txt\nself.used = true\n",
							name = "Record Monitor positions",
							uuid = "21641bdb-b7ca-e0f7-ac28-4b02e8f090d5",
							version = 2.1,
						},
					},
				},
