					{
						data = 
						{
							aType = "Lua",
							actionLua = "local AM = data.topAM\nif AM == nil then self.used = true return end\nlocal v = AM.store.values\nlocal enabled = v.enabled == true and v.monitor == true\n-- Place the marks until the beams have landed (571.4 + 3.6), then clear the ones we put on.\nif enabled and v.clear ~= false and (TensorReactions_CurrentTimer or 0) >= 575 then\n    local queue = AM.snapshots[\"monitor\"]\n    if queue then\n        local ids = {}\n        for _, a in ipairs(queue) do ids[#ids + 1] = a.id end\n        AM.clearTick(\"monitor\", ids)\n    end\nelse\n    AM.tick(\"monitor\", enabled and AM.snapshot(\"monitor\", AM.buildMonitor) or nil, enabled)\nend\nself.used = true\n",
