							aType = "Lua",
							actionLua = "local AM = data.topAM\nif AM == nil then self.used = true return end\nlocal v = AM.store.values\nlocal enabled = v.enabled == true and v.delta == true\nlocal t = TensorReactions_CurrentTimer or 0\nif enabled and v.clear ~= false and t >= 788.5 then\n    local queue = AM.snapshots[\"delta\"]\n    if queue then\n        local ids = {}\n        for _, a in ipairs(queue) do ids[#ids + 1] = a.id end\n        AM.clearTick(\"delta\", ids)\n    end\nelse\n    local queue = enabled and AM.snapshot(\"delta\", AM.buildDelta) or nil\n    AM.tick(\"delta\", queue, enabled)\nend\nself.used = true\n",
