						{
							aType = "Lua",
							actionLua = "local AM = data.topAM\nif AM == nil then self.used = true return end\nlocal v = AM.store.values\nlocal enabled = v.enabled == true and v.sigma == true\nlocal t = TensorReactions_CurrentTimer or 0\nif enabled and v.clear ~= false and t >= 881.5 then\n    local queue = AM.snapshots[\"sigma\"]\n    if queue then\n        local ids = {}\n        for _, a in ipairs(queue) do ids[#ids + 1] = a.id end\n        AM.clearTick(\"sigma\", ids)\n    end\nelse\n    local queue = enabled and AM.snapshot(\"sigma\", AM.buildSigma) or nil\n    if queue and Now() - (AM.snapAt[\"sigma\"] or Now()) < 30000 then queue = nil end\n    AM.tick(\"sigma\", queue, enabled)\nend\nself.used = true\n",
