						{
							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 41 then\n    cfg = {\n        version = 41,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- Mana: arrow to my Wave Cannon Kyrios spot after Pantokrator.\n            kyrArrow = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Line colour for the \"Tether\" style (the user, 2026-11-15; it used to come out white).\n            tetherColor = \"Red\",\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Tether line colours (ABGR). Every colour slot of the line drawer gets the same one: with a white outline slot the\n    -- line came out white.\n    cfg.TETHER_COLOR_NAMES = { \"Red\", \"Orange\", \"Yellow\", \"Green\", \"Cyan\", \"Blue\", \"Magenta\", \"White\" }\n    cfg.TETHER_COLORS = { Red = 0xFF0000FF, Orange = 0xFF0088FF, Yellow = 0xFF00FFFF, Green = 0xFF00FF00, Cyan = 0xFFFFFF00,\n                          Blue = 0xFFFF0000, Magenta = 0xFFFF00FF, White = 0xFFFFFFFF }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                local colors = live.TETHER_COLORS or {}\n                local color = colors[live.values.tetherColor] or 0xFF0000FF\n                live.tetherDrawers = live.tetherDrawers or {}\n                local drawer = live.tetherDrawers[color]\n                if drawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    drawer = TensorCore.getCachedDrawer(color, color, color, color, 2, 0, overlay)\n                    live.tetherDrawers[color] = drawer\n                end\n                drawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() and not (Roster.state and Roster.state()) then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        local naur = Roster.state and Roster.state()\n        if naur then\n            saved = { members = {}, jobs = {} }\n            for slot, row in pairs(naur.bySlot) do saved.members[row.key] = slot; saved.jobs[row.key] = row.job end\n        end\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P5 Run: Dynamis Omega dodges: predraws of the M and F clones' attacks, one pair at a time, in either of two styles.\n-- Safe area draw: a green floor with every active attack cut out, Omega's cleaves included, so green is what's safe.\n-- Normal draw: timed red shapes for the clones, where the safe place is simply wherever isn't red.\nlocal values = cfg.values\nlocal t = TensorReactions_CurrentTimer\nlocal s = data.topOmegaClones\nif s == nil or (s.lastTime and (t < s.lastTime - 5 or Now() - (s.lastClock or Now()) > 5000)) then\n    s = {}\n    data.topOmegaClones = s\nend\ns.lastTime = t\ns.lastClock = Now()\nif not values.omeClones then\n    self.used = true\n    return\nend\n\nif not s.initialized then\n    s.initialized = true\n    s.seen, s.warned = {}, {}\n    s.count = { M = 0, F = 0 }\n    s.pairs = { {}, {} }\n    s.HITS = { 928.8, 932.8 }\n    -- Omega's cleaves land just after the clones. The second set takes over when the first has landed.\n    s.CLEAVE_HITS = { 928.95, 933.0 }\n    -- doNotDetect is on for the timed draws: these must never count as AOEs for anything that reads custom draws.\n    s.drawDanger = TensorCore.getCachedDrawer(0x140000FF, 0x280000FF, 0x550000FF, 0x880000FF, 1.5)\n    s.drawPreview = TensorCore.getCachedDrawer(0x04FFFFFF, 0x04FFFFFF, 0x04FFFFFF, 0x66FFFFFF, 1)\n    -- The floor and blockers are this script's own drawers, because their channel changes every frame.\n    local flags = Argus2.RenderFlags\n    s.FLOOR_FLAGS = flags.FLAG_OCCLUSION_BASE | flags.FLAG_WARP_TERRAIN\n    s.BLOCK_FLAGS = flags.FLAG_OCCLUDE | flags.FLAG_WARP_TERRAIN\n    s.drawFloor = Argus2.ShapeDrawer:new(0x5500FF00, 0x5500FF00, 0x5500FF00, nil, 0)\n    s.drawFloor:setGradient(0, 1, 0)\n    s.drawBlock = Argus2.ShapeDrawer:new(0x00000000, 0x00000000, 0x00000000, nil, 0)\n\n    function s.log(text)\n        d(\"[Omega] \" .. text)\n        TensorCore.timelineLogToFile(\"[Omega] \" .. text .. \"\\n\")\n    end\n\n    -- Sizes as in MuAi's TOP profile. A rect starts at its point and runs along the heading; its width is the full width.\n    -- The cross is long enough to reach the far rim whether its length means each arm or the whole bar.\n    function s.shapes(kind, p)\n        if kind == \"sword\" then\n            return { { \"Circle\", p.x, p.y, p.z, 10 } }\n        elseif kind == \"shield\" then\n            -- M stands at r=10, so 30 reaches the far rim.\n            return { { \"Donut\", p.x, p.y, p.z, 10, 30 } }\n        elseif kind == \"staff\" then\n            return { { \"Cross\", p.x, p.y, p.z, 60, 10, p.h } }\n        end\n        -- Both sides of the 8y lane through F. She stands at r=10 facing the centre, so each side starts level with the\n        -- centre, 4 off the lane, and runs out to the rim.\n        local cx, cz = p.x + 10 * math.sin(p.h), p.z + 10 * math.cos(p.h)\n        local list = {}\n        for _, side in ipairs({ p.h + math.pi / 2, p.h - math.pi / 2 }) do\n            list[#list + 1] = { \"Rect\", cx + 4 * math.sin(side), p.y, cz + 4 * math.cos(side), 16, 40, side }\n        end\n        return list\n    end\n\n    function s.timed(drawer, kind, p, timeout, delay)\n        for _, shape in ipairs(s.shapes(kind, p)) do\n            local name = shape[1]\n            if name == \"Circle\" then\n                drawer:addTimedCircle(timeout, shape[2], shape[3], shape[4], shape[5], delay, nil, true)\n            elseif name == \"Donut\" then\n                drawer:addTimedDonut(timeout, shape[2], shape[3], shape[4], shape[5], shape[6], delay, nil, true)\n            elseif name == \"Cross\" then\n                drawer:addTimedCross(timeout, shape[2], shape[3], shape[4], shape[5], shape[6], shape[7], delay, nil, true)\n            else\n                drawer:addTimedRect(timeout, shape[2], shape[3], shape[4], shape[5], shape[6], shape[7], delay, nil, true)\n            end\n        end\n    end\n\n    function s.block(kind, p)\n        for _, shape in ipairs(s.shapes(kind, p)) do\n            local name = shape[1]\n            if name == \"Circle\" then\n                s.drawBlock:addCircle(shape[2], shape[3], shape[4], shape[5], false, s.BLOCK_FLAGS)\n            elseif name == \"Donut\" then\n                s.drawBlock:addDonut(shape[2], shape[3], shape[4], shape[5], shape[6], false, s.BLOCK_FLAGS)\n            elseif name == \"Cross\" then\n                s.drawBlock:addCross(shape[2], shape[3], shape[4], shape[5], shape[6], shape[7], false, s.BLOCK_FLAGS)\n            else\n                s.drawBlock:addRect(shape[2], shape[3], shape[4], shape[5], shape[6], shape[7], false, s.BLOCK_FLAGS)\n            end\n        end\n    end\n\n    function s.schedule(kind, p, index, t, values)\n        local from = index == 1 and t or math.max(t, s.HITS[1])\n        local to = s.HITS[index]\n        if to <= t then return end\n        s.timed(s.drawDanger, kind, p, (to - from) * 1000, (from - t) * 1000)\n        if index == 2 and values.omePreview and t < s.HITS[1] then\n            s.timed(s.drawPreview, kind, p, (s.HITS[1] - t) * 1000, 0)\n        end\n    end\n\n    function s.scan(content, model, sex, kinds, t, values)\n        for id, e in pairs(TensorCore.entityList(\"contentid=\" .. content)) do\n            if not s.seen[id] and Argus.getEntityModel(e) == model and Argus.isEntityVisible(e) then\n                local _, flags = Argus.getEntityTransforms(e)\n                local kind = kinds[flags]\n                if kind then\n                    s.seen[id] = true\n                    s.count[sex] = s.count[sex] + 1\n                    local index = s.count[sex]\n                    if index <= 2 then\n                        local p = { x = e.pos.x, y = e.pos.y, z = e.pos.z, h = e.pos.h }\n                        s.pairs[index][sex] = { kind = kind, pos = p }\n                        if not values.omeSafe then s.schedule(kind, p, index, t, values) end\n                        s.log(string.format(\"%.1f pair %d %s\", t, index, kind))\n                    end\n                elseif not s.warned[id] then\n                    s.warned[id] = true\n                    s.log(string.format(\"%.1f clone %s has unknown weapon flags %s\", t, sex, tostring(flags)))\n                end\n            end\n        end\n    end\n\n    -- 31644 cleaves Omega's sides first, 31643 her front and back first.\n    function s.readCleaves(t)\n        for _, e in pairs(TensorCore.entityList(\"contentid=7636\")) do\n            local channel = e.castinginfo and e.castinginfo.channelingid\n            if Argus.getEntityModel(e) == 14669 and (channel == 31644 or channel == 31643) then\n                s.sidesFirst = channel == 31644\n                s.omega = { x = e.pos.x, y = e.pos.y, z = e.pos.z, h = e.pos.h }\n                s.log(string.format(\"%.1f cleaves %s first\", t, s.sidesFirst and \"sides\" or \"front and back\"))\n            end\n        end\n    end\n\n    function s.blockCleaves(phase)\n        local p = s.omega\n        local sides = s.sidesFirst\n        if phase == 2 then sides = not sides end\n        local h = sides and p.h + math.pi / 2 or p.h\n        local angle = 130 / 180 * math.pi\n        s.drawBlock:addCone(p.x, p.y, p.z, 30, angle, h, false, s.BLOCK_FLAGS)\n        s.drawBlock:addCone(p.x, p.y, p.z, 30, angle, h + math.pi, false, s.BLOCK_FLAGS)\n    end\n\n    -- Green only shows once everything hitting in this phase is known, so it never marks a spot that isn't safe.\n    function s.drawSafeArea(t)\n        local phase\n        if t < s.CLEAVE_HITS[1] then phase = 1 elseif t < s.CLEAVE_HITS[2] then phase = 2 end\n        if phase == nil or s.omega == nil then return end\n        local clones = s.pairs[phase]\n        if clones.M == nil or clones.F == nil then return end\n        local channel = Argus2.getNextUnusedChannel(true)\n        if channel == nil then\n            if not s.warned.channel then\n                s.warned.channel = true\n                s.log(\"no free draw channel for the safe area\")\n            end\n            return\n        end\n        s.drawFloor:setOcclusionChannel(channel)\n        s.drawBlock:setOcclusionChannel(channel)\n        s.drawFloor:addCircle(100, s.omega.y, 100, 20, false, s.FLOOR_FLAGS)\n        if t < s.HITS[phase] then\n            s.block(clones.M.kind, clones.M.pos)\n            s.block(clones.F.kind, clones.F.pos)\n        end\n        s.blockCleaves(phase)\n    end\nend\n\nlocal clock = Now()\nif t < s.CLEAVE_HITS[2] and (s.count.M < 2 or s.count.F < 2 or s.omega == nil) then\n    if s.nextPass == nil or clock >= s.nextPass then\n        s.nextPass = clock + 100\n        s.scan(12257, 15721, \"M\", { [16] = \"sword\", [49] = \"shield\" }, t, values)\n        s.scan(12258, 15722, \"F\", { [16] = \"staff\", [49] = \"feet\" }, t, values)\n        if s.omega == nil then s.readCleaves(t) end\n    end\nend\nif values.omeSafe then s.drawSafeArea(t) end\nself.used = true\n",
