						data = 
						{
							aType = "Lua",
							actionLua = "local AM = data.topAM\nif AM == nil then self.used = true return end\nlocal v = AM.store.values\nlocal enabled = v.enabled == true and v.omega == true\nlocal t = TensorReactions_CurrentTimer or 0\nif enabled and v.clear ~= false and t >= 966.5 then\n    local ids = {}\n    for _, key in ipairs({ \"omega1\", \"omega2\" }) do\n        for _, a in ipairs(AM.snapshots[key] or {}) do ids[#ids + 1] = a.id end\n    end\n    if #ids > 0 then AM.clearTick(\"omega\", ids) end\nelseif enabled and t >= 948.5 and AM.snapshots.omega2 then\n    -- Set 2 once the first Hello, Distant World has landed (Dynamis stacks 946-948).\n    AM.tick(\"omega2\", AM.snapshots.omega2, true)\nelse\n    AM.tick(\"omega1\", enabled and AM.snapshot(\"omega1\", AM.buildOmega) or nil, enabled)\nend\nself.used = true\n",
