				mechanicTime = 927.8,
				name = "P5_3运绘制波动炮",
				timeRange = true,
				timelineIndex = 189,
				timerStartOffset = -20,
				uuid = "ea4941e4-b8db-6947-845e-5e1f5988f3a5",
