					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- TOP P6 Unlimited Wave Cannon: records the exaflare starts in order (31661, channelled 11.7s before they fire, at r=24 on the\n-- wall) and each puddle bait (31663, eight at once, one per player, about 2s apart).\nlocal t = TensorReactions_CurrentTimer\nlocal clock = Now()\nlocal s = data.topUwc\nif s == nil or clock - s.at > 30000 then\n    s = { at = clock, exas = {}, baits = {} }\n    data.topUwc = s\nend\nif eventArgs.spellID == 31661 then\n    local e = TensorCore.mGetEntity(eventArgs.entityID)\n    if e and e.pos then\n        s.exas[#s.exas + 1] = { bearing = math.deg(math.atan2(e.pos.x - 100, 100 - e.pos.z)) % 360, t = t }\n    end\nelseif eventArgs.spellID == 31663 then\n    -- each puddle's position, for the slim outlines in [UWC] Arrow (2026-11-23)\n    local pe = TensorCore.mGetEntity(eventArgs.entityID)\n    s.puddles = s.puddles or {}\n    if pe and pe.pos then s.puddles[#s.puddles + 1] = { x = pe.pos.x, z = pe.pos.z, at = clock } end\n    local last = s.baits[#s.baits]\n    if last == nil or t - last > 1 then\n        s.baits[#s.baits + 1] = t\n    end\nend\nself.used = true\n",
