						{
							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 41 then\n    cfg = {\n        version = 41,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- Mana: arrow to my Wave Cannon Kyrios spot after Pantokrator.\n            kyrArrow = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Line colour for the \"Tether\" style (the user, 2026-11-15; it used to come out white).\n            tetherColor = \"Red\",\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Tether line colours (ABGR). Every colour slot of the line drawer gets the same one: with a white outline slot the\n    -- line came out white.\n    cfg.TETHER_COLOR_NAMES = { \"Red\", \"Orange\", \"Yellow\", \"Green\", \"Cyan\", \"Blue\", \"Magenta\", \"White\" }\n    cfg.TETHER_COLORS = { Red = 0xFF0000FF, Orange = 0xFF0088FF, Yellow = 0xFF00FFFF, Green = 0xFF00FF00, Cyan = 0xFFFFFF00,\n                          Blue = 0xFFFF0000, Magenta = 0xFFFF00FF, White = 0xFFFFFFFF }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                local colors = live.TETHER_COLORS or {}\n                local color = colors[live.values.tetherColor] or 0xFF0000FF\n                live.tetherDrawers = live.tetherDrawers or {}\n                local drawer = live.tetherDrawers[color]\n                if drawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    drawer = TensorCore.getCachedDrawer(color, color, color, color, 2, 0, overlay)\n                    live.tetherDrawers[color] = drawer\n                end\n                drawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() and not (Roster.state and Roster.state()) then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        local naur = Roster.state and Roster.state()\n        if naur then\n            saved = { members = {}, jobs = {} }\n            for slot, row in pairs(naur.bySlot) do saved.members[row.key] = slot; saved.jobs[row.key] = row.job end\n        end\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P6 Cosmo Arrow, \"Exa-squares\": an arrow to each dodge step, from the P6 deck's step lists, and a small ring on the next one.\n-- The first goes to the corner I'm closest to when it starts (the user, 2026-11-10; every preset), on the DPS steps. The second\n-- is dodged from my own clockspot: DPS in their intercard, supports on\n-- their cardinal: tanks on the east side (T1 NE, T2 SE), healers on the south side (H2 SE, H1 SW), as the user's static did in both\n-- logged pulls (2026-11-08). Each step starts when the wave before it lands.\nlocal values = cfg.values\nlocal t = TensorReactions_CurrentTimer\nlocal exa = data.topExa\nlocal s = data.topExaDodge\n-- data outlives a redeploy, so a new revision rebuilds the tables below instead of keeping an older copy's.\nlocal REV = \"2026-11-08-style\"\nif s == nil or s.rev ~= REV then\n    s = { warned = {}, rev = REV }\n    data.topExaDodge = s\n    -- { starts this long after the first cast, DPS { along, side }, support { along, side } }. Offsets out from the middle on both axes;\n    -- a 5y line at 100 +/- c hits offsets c-2.5 to c+2.5. Wave times are from the 11:23 (In) and 14:12 (Out) pulls on 2026-11-07.\n    s.STEPS = {\n        -- In > Wait > Out past marker > Wait > Wait > In. Supports (the user's list, 2026-11-08): In > Wait > Out > Wait next to the\n        -- middle 2 exas > Dodge to side (out of hitbox) > In > Done.\n        inside = { { 0, { 6.5, 6.5 }, { 6.5, 6.5 } }, { 8.0, { 3, 3 }, { 3, 3 } }, { 12.1, { 12, 12 }, { 12, 12 } },\n                   { 14.1, { 12, 12 }, { 12, 6 } }, { 16.1, { 12, 12 }, { 12, 1 } }, { 18.2, { 7.5, 7.5 }, { 7.5, 1 } } },\n        -- Out > Wait > In > Out > In. Supports (the user's list): Out > Wait > In > Dodge to marker > In.\n        outside = { { 0, { 7.5, 7.5 }, { 7.5, 7.5 } }, { 8.0, { 12.5, 12.5 }, { 12.5, 12.5 } }, { 12.1, { 7.5, 7.5 }, { 7.5, 6 } },\n                    { 14.1, { 12.5, 12.5 }, { 12.5, 1 } }, { 16.1, { 7.5, 7.5 }, { 7.5, 1 } } },\n    }\n    -- The last wave lands at +22.0 (In) and +20.1 (Out).\n    s.LAST = { inside = 22.0, outside = 20.1 }\n    s.FIRST_BEFORE = 1220\n    -- NA strat (the user, 2026-11-08): R2 NE and R1 NW, the same as the P6 clock spots.\n    s.BEARING = { T1 = 0, R2 = 45, H2 = 90, M2 = 135, T2 = 180, M1 = 225, H1 = 270, R1 = 315 }\n    s.SUPPORT = { T1 = true, T2 = true, H1 = true, H2 = true }\n    -- Which side of the cardinal: +1 clockwise, -1 counter-clockwise. Steps 4-5 stand 1y off the line, where the tanks stood.\n    s.SIDE = { T1 = 1, T2 = -1, H2 = 1, H1 = -1 }\n    -- Option exaDpsSupport (the user's picture, 2026-11-08): DPS take the support steps along the E/W line by their corner,\n    -- R1 W north, M1 W south, R2 E north, M2 E south.\n    s.DPS_CARDINAL = { R1 = 270, M1 = 270, R2 = 90, M2 = 90 }\n    s.DPS_SIDE = { R1 = 1, M1 = -1, R2 = -1, M2 = 1 }\n    -- With that option on, supports follow the same picture so nobody shares a line: tanks on the N line (MT west, OT east),\n    -- healers on the S line (H1 west, H2 east).\n    s.SUP_WITH_DPS = { T1 = { 0, -1 }, T2 = { 0, 1 }, H1 = { 180, 1 }, H2 = { 180, -1 } }\n    -- Elemental (ffxiv.tuufless.com/elemental/top/06_alpha_omega, images 1_04a, 3_04a-3_09a): the first is dodged with the party\n    -- SW, MT NW and ST SE. The second in corner pairs that split at the spread: MT NW, D3 N, D4 NE, H2 E, D2 SE, ST S, D1 SW, H1 W,\n    -- each cardinal player coming from the corner counter-clockwise of their cardinal.\n    s.ELEMENTAL_FIRST = { T1 = 315, T2 = 135 }\n    s.ELEMENTAL_SECOND = { T1 = 315, R1 = 0, R2 = 45, H2 = 90, M2 = 135, T2 = 180, M1 = 225, H1 = 270 }\n    s.ELEMENTAL_CARDINAL = { R1 = true, H2 = true, T2 = true, H1 = true }\n    -- OCE (MUR cheatsheet): the first with the party SW, \"MT -> CW, ST -> CCW\": MT side-steps to W from the south side, ST to S\n    -- from the west side, with the support steps. The second in intercard pairs (H1+D3 NW, MT+D4 NE, D1+ST SW, H2+D2 SE), \"DPS\n    -- dodge CW, Supports CCW\": everyone takes the support steps on the cardinal next to their corner, DPS the one clockwise\n    -- (coming from its counter-clockwise side, -1), supports the one counter-clockwise (coming from its clockwise side, +1).\n    s.OCE_FIRST = { T1 = { 270, -1 }, T2 = { 180, 1 } }\n    s.OCE_SECOND = { T1 = { 0, 1 }, H2 = { 90, 1 }, T2 = { 180, 1 }, H1 = { 270, 1 },\n                     R1 = { 0, -1 }, R2 = { 90, -1 }, M2 = { 180, -1 }, M1 = { 270, -1 } }\n    -- LDPU (raidplan mh3bX4KJ9d8rT9nk, \"Wave cannon 2\"): corner pairs MT+Phys NW, OT+Caster NE, M1+H1 SW, H2+M2 SE, then the\n    -- \"Side dodges\" picture: tanks on the N line (MT west, OT east), healers on the S line, Phys W north, M1 W south, Caster E\n    -- north, M2 E south. Ranged by job (P = physical ranged, C = caster), as the clock spots.\n    s.LDPU_SECOND = { T1 = { 0, -1 }, T2 = { 0, 1 }, H1 = { 180, 1 }, H2 = { 180, -1 },\n                      P = { 270, 1 }, M1 = { 270, -1 }, C = { 90, -1 }, M2 = { 90, 1 } }\n    -- The same rule as [Clock Spot]: whichever of R1/R2 is BRD, MCH or DNC; R2 when both or neither are.\n    function s.physSlot(view, me)\n        local PHYSICAL = { [23] = true, [31] = true, [38] = true }\n        local function physical(slot)\n            local id = view.idOf(slot)\n            if id == nil then return false end\n            if me and id == me.id then return PHYSICAL[me.job] == true end\n            local e = TensorCore.mGetEntity(id)\n            return e ~= nil and PHYSICAL[e.job] == true\n        end\n        if physical(\"R1\") and not physical(\"R2\") then return \"R1\" end\n        return \"R2\"\n    end\n    s.drawArrow = cfg.styledArrow(\"stExa\", TensorCore.getCachedDrawer(0xFF00FFFF, 0xFF0088FF, 0xFF0000FF, 0xFFFFFFFF, 2))\n    s.drawMine = TensorCore.getCachedDrawer(nil, nil, 0x6600FF00, 0xFF00FF00, 2)\n    s.drawNext = TensorCore.getCachedDrawer(nil, nil, 0x44FFFFFF, 0xFFFFFFFF, 2)\n\n    function s.warnOnce(key, text)\n        if not s.warned[key] then\n            s.warned[key] = true\n            d(\"[Exa] \" .. text)\n            TensorCore.timelineLogToFile(\"[Exa] \" .. text .. \"\\n\")\n        end\n    end\n\n    -- An intercard: both offsets go out into that corner. A cardinal: \"along\" goes out along it, \"side\" to its clockwise side (side < 0: counter-clockwise).\n    function s.place(bearing, offsets, support, side)\n        local a, b = offsets[1], offsets[2] * (side or 1)\n        if support then\n            local u = math.rad(bearing)\n            local v = math.rad(bearing + 90)\n            return { x = 100 + a * math.sin(u) + b * math.sin(v), z = 100 - a * math.cos(u) - b * math.cos(v) }\n        end\n        local r = math.rad(bearing)\n        local sx = math.sin(r) > 0 and 1 or -1\n        local sz = -math.cos(r) > 0 and 1 or -1\n        return { x = 100 + sx * a, z = 100 + sz * b }\n    end\nend\n\nlocal me = TensorCore.mGetPlayer()\nif not values.exaArrow or exa == nil or exa.first == nil or me == nil or me.pos == nil then\n    self.used = true\n    return\nend\n-- A new Cosmo Arrow: start the log lines afresh.\nif s.first ~= exa.first then\n    s.first = exa.first\n    s.warned = {}\nend\nlocal pattern = exa.isIn and \"inside\" or \"outside\"\nlocal since = t - exa.first\nif since < 0 or since >= s.LAST[pattern] then\n    self.used = true\n    return\nend\n\nlocal bearing, support, side\nlocal elementalSlot\nif values.elemental or values.oce or values.mana then\n    local Roster = NAUR_Roster or (AnyoneCore and AnyoneCore.Roster)\n    local view = Roster and Roster.current() ~= nil and cfg.rosterView(Roster, me) or nil\n    elementalSlot = view and view.mySlot()\nend\nif exa.first < s.FIRST_BEFORE then\n    -- The first Exasquare (the user, 2026-11-10): the corner closest to where I stand when it starts, whatever my role or the\n    -- preset, then that corner's DPS steps (every corner's steps clear the waves). Locked for this Cosmo Arrow; dead centre is SW.\n    if s.cornerFor ~= exa.first then\n        local dx, dz = me.pos.x - 100, me.pos.z - 100\n        local corner = 225\n        if math.abs(dx) > 0.3 or math.abs(dz) > 0.3 then\n            if dx >= 0 then corner = dz < 0 and 45 or 135 else corner = dz < 0 and 315 or 225 end\n        end\n        s.corner, s.cornerFor = corner, exa.first\n    end\n    bearing, support = s.corner, false\nelseif values.elemental or values.mana then\n    -- Mana's Wave Cannon 2 pairs (MT+D3 NW, H2+D4 NE, H1+D1 SW, ST+D2 SE) are Elemental's second Exasquare.\n    if elementalSlot == nil or s.ELEMENTAL_SECOND[elementalSlot] == nil then\n        s.warnOnce(\"roster\", \"no Party Roster: can't tell my clockspot for the second Exasquare\")\n        self.used = true\n        return\n    end\n    bearing = s.ELEMENTAL_SECOND[elementalSlot]\n    support = s.ELEMENTAL_CARDINAL[elementalSlot] == true\n    side = support and -1 or nil\nelseif values.oce then\n    local row = s.OCE_SECOND[elementalSlot]\n    if row == nil then\n        s.warnOnce(\"roster\", \"no Party Roster: can't tell my corner for the second Exasquare\")\n        self.used = true\n        return\n    end\n    bearing, support, side = row[1], true, row[2]\nelseif values.ldpu then\n    local Roster = NAUR_Roster or (AnyoneCore and AnyoneCore.Roster)\n    local view = Roster and Roster.current() ~= nil and cfg.rosterView(Roster, me) or nil\n    local slot = view and view.mySlot()\n    if slot == \"R1\" or slot == \"R2\" then\n        local ok, phys = pcall(s.physSlot, view, me)\n        slot = (ok and slot == phys or (not ok and slot == \"R2\")) and \"P\" or \"C\"\n    end\n    local row = slot and s.LDPU_SECOND[slot]\n    if row == nil then\n        s.warnOnce(\"roster\", \"no Party Roster: can't tell my corner for the second Exasquare\")\n        self.used = true\n        return\n    end\n    bearing, support, side = row[1], true, row[2]\nelse\n    local Roster = NAUR_Roster or (AnyoneCore and AnyoneCore.Roster)\n    local view = Roster and Roster.current() ~= nil and cfg.rosterView(Roster, me) or nil\n    local slot = view and view.mySlot()\n    if slot == nil or s.BEARING[slot] == nil then\n        s.warnOnce(\"roster\", \"no Party Roster: can't tell my clockspot for the second Exasquare\")\n        self.used = true\n        return\n    end\n    bearing, support, side = s.BEARING[slot], s.SUPPORT[slot] == true, s.SIDE[slot]\n    if support and values.exaDpsSupport and s.SUP_WITH_DPS[slot] then\n        bearing, side = s.SUP_WITH_DPS[slot][1], s.SUP_WITH_DPS[slot][2]\n    elseif not support and values.exaDpsSupport and s.DPS_CARDINAL[slot] then\n        bearing, support, side = s.DPS_CARDINAL[slot], true, s.DPS_SIDE[slot]\n    end\nend\n\nlocal steps = s.STEPS[pattern]\nlocal index = 1\nfor i, row in ipairs(steps) do\n    if since >= row[1] then index = i end\nend\nlocal spot = s.place(bearing, steps[index][support and 3 or 2], support, side)\nlocal nextRow = steps[index + 1]\nlocal y = me.pos.y\ns.drawMine:addCircle(spot.x, y, spot.z, 0.8)\nif nextRow then\n    local nextSpot = s.place(bearing, nextRow[support and 3 or 2], support, side)\n    if math.abs(nextSpot.x - spot.x) > 0.1 or math.abs(nextSpot.z - spot.z) > 0.1 then\n        s.drawNext:addCircle(nextSpot.x, y, nextSpot.z, 0.5)\n    end\nend\nlocal dx, dz = spot.x - me.pos.x, spot.z - me.pos.z\nlocal dist = math.sqrt(dx * dx + dz * dz)\nif dist > 0.5 and me.hp.current > 0 then\n    -- Sized like the standard guide arrow, except it keeps pointing up close.\n    local scale = math.min(1, dist / 15)\n    local near = math.min(1, dist / 3)\n    local tipLength = math.min(math.max(2, 3 * scale), dist * 2 / 3)\n    s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spot.x, y, spot.z),\n        dist - tipLength, math.max(0.5, scale) * near, tipLength, math.max(1.5, 3 * scale) * near,\n        false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\nend\nself.used = true\n",
							name = "Draw Exasquare Dodge",
							uuid = "367701bc-5567-de4b-ac6d-b8c3e5263c43",
							version = 2.1,
						},
					},
				},
