	[251] = 
	{
		
		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- TOP P6 Unlimited Wave Cannon: records the exaflare starts in order (31661, channelled 11.7s before they fire, at r=24 on the\n-- wall) and each puddle bait (31663, eight at once, one per player, about 2s apart).\nlocal t = TensorReactions_CurrentTimer\nlocal clock = Now()\nlocal s = data.topUwc\nif s == nil or clock - s.at > 30000 then\n    s = { at = clock, exas = {}, baits = {} }\n    data.topUwc = s\nend\nif eventArgs.spellID == 31661 then\n    local e = TensorCore.mGetEntity(eventArgs.entityID)\n    if e and e.pos then\n        s.exas[#s.exas + 1] = { bearing = math.deg(math.atan2(e.pos.x - 100, 100 - e.pos.z)) % 360, t = t }\n    end\nelseif eventArgs.spellID == 31663 then\n    -- each puddle's position, for the slim outlines in [UWC] Arrow (2026-11-23)\n    local pe = TensorCore.mGetEntity(eventArgs.entityID)\n    s.puddles = s.puddles or {}\n    if pe and pe.pos then s.puddles[#s.puddles + 1] = { x = pe.pos.x, z = pe.pos.z, at = clock } end\n    local last = s.baits[#s.baits]\n    if last == nil or t - last > 1 then\n        s.baits[#s.baits + 1] = t\n    end\nend\nself.used = true\n",
							conditions = 
							{
								
								{
									"c4322f26-3081-3dc5-8c21-d7e70df0bd27",
									true,
								},
							},
							name = "Record Unlimited Wave Cannon",
							uuid = "c29a32e6-d062-b275-a8a5-0110f309ab16",
							version = 2.1,
						},
					},
				},
				conditions = 
				{
					
					{
						data = 
						{
							category = "Event",
							dequeueIfLuaFalse = true,
							eventArgOptionType = 3,
							eventArgType = 2,
							name = "Spells",
							spellIDList = 
							{
								31661,
								31663,
							},
							uuid = "c4322f26-3081-3dc5-8c21-d7e70df0bd27",
							version = 3,
						},
					},
				},
				eventType = 3,
				loop = true,
				mechanicTime = 1291.7,
				name = "[UWC] Casts 2",
				timeRange = true,
				timelineIndex = 251,
				timerEndOffset = 21,
				timerStartOffset = -6,
				uuid = "536d3e90-a3ab-e60a-af7d-aedb0a23a1ba",
				version = 2,
			},
		},
		
		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 41 then\n    cfg = {\n        version = 41,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- Mana: arrow to my Wave Cannon Kyrios spot after Pantokrator.\n            kyrArrow = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Line colour for the \"Tether\" style (the user, 2026-11-15; it used to come out white).\n            tetherColor = \"Red\",\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Tether line colours (ABGR). Every colour slot of the line drawer gets the same one: with a white outline slot the\n    -- line came out white.\n    cfg.TETHER_COLOR_NAMES = { \"Red\", \"Orange\", \"Yellow\", \"Green\", \"Cyan\", \"Blue\", \"Magenta\", \"White\" }\n    cfg.TETHER_COLORS = { Red = 0xFF0000FF, Orange = 0xFF0088FF, Yellow = 0xFF00FFFF, Green = 0xFF00FF00, Cyan = 0xFFFFFF00,\n                          Blue = 0xFFFF0000, Magenta = 0xFFFF00FF, White = 0xFFFFFFFF }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                local colors = live.TETHER_COLORS or {}\n                local color = colors[live.values.tetherColor] or 0xFF0000FF\n                live.tetherDrawers = live.tetherDrawers or {}\n                local drawer = live.tetherDrawers[color]\n                if drawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    drawer = TensorCore.getCachedDrawer(color, color, color, color, 2, 0, overlay)\n                    live.tetherDrawers[color] = drawer\n                end\n                drawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() and not (Roster.state and Roster.state()) then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        local naur = Roster.state and Roster.state()\n        if naur then\n            saved = { members = {}, jobs = {} }\n            for slot, row in pairs(naur.bySlot) do saved.members[row.key] = slot; saved.jobs[row.key] = row.job end\n        end\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P6 Unlimited Wave Cannon (P6 deck slides 11, 12, 16): an arrow to each of the six puddle baits, a green ring on it and a red\n-- ring on the next. The party stacks middle. The dodge marker is the one next to the 1st exaflare, away from the 2nd. After the 1st\n-- puddle the party moves toward the wall at that marker, then rotates toward the 1st exaflare, each bait on the edge of the last\n-- (puddles are r=6, so 6y apart). After the 6th: UWC1 hands over to [Clock Spot] Wave Cannon 1; UWC2 plants on the boss hitbox.\nlocal values = cfg.values\nlocal t = TensorReactions_CurrentTimer\nlocal REV = \"2026-11-23-look\"\nlocal s = data.topUwcArrow\nif s == nil or s.rev ~= REV then\n    s = { rev = REV, warned = {} }\n    data.topUwcArrow = s\n    -- Each bait lands about 1s after I've moved on, so the next spot must clear the last puddle (r=6) with room: 9y steps along the\n    -- wall (about 30 degrees at r=17), as the user's party did in the replayed pull. Toward the wall in 7y steps: 14y keeps the 3rd\n    -- bait about 10y clear of the 1st exaflare's 3rd hit.\n    s.STEP = 9\n    s.OUT = 7\n    s.WALL = 17\n    s.TURN = math.deg(2 * math.asin(s.STEP / 2 / s.WALL))\n    s.ELEMENTAL = { OUT1 = 5, OUT2 = 10, WALL = 14, TURN = 30 }\n    s.UWC2_FROM = 1280\n    s.DIVE = 1312.4\n    s.drawArrow = cfg.styledArrow(\"stUwc\", TensorCore.getCachedDrawer(0xFF00FFFF, 0xFF0088FF, 0xFF0000FF, 0xFFFFFFFF, 2))\n    -- cleaner look (2026-11-23): outline rings, amber for the next spot, slim outlines on the puddles until they land\n    s.drawMine = TensorCore.getCachedDrawer(nil, nil, 0x1A00FF00, 0xFF00FF00, 2.5)\n    s.drawNext = TensorCore.getCachedDrawer(nil, nil, 0x0000AAFF, 0xFF00AAFF, 2)\n    s.drawPuddle = TensorCore.getCachedDrawer(nil, nil, 0x120000FF, 0xCC0000FF, 1.5)\n\n    function s.warnOnce(key, text)\n        if not s.warned[key] then\n            s.warned[key] = true\n            d(\"[UWC] \" .. text)\n            TensorCore.timelineLogToFile(\"[UWC] \" .. text .. \"\\n\")\n        end\n    end\n\n    function s.at(bearing, radius)\n        local a = math.rad(bearing)\n        return { x = 100 + radius * math.sin(a), z = 100 - radius * math.cos(a) }\n    end\n\n    -- The six bait spots from the first two exaflare starts: marker and turn direction.\n    function s.plan(first, second)\n        local delta = (second - first + 540) % 360 - 180\n        local sign = delta > 0 and 1 or -1\n        local mid = { x = 100, z = 100 }\n        if values.elemental then\n            -- Elemental (06_alpha_omega, images 2_1-2_3): out 1.5 markers (67.5 degrees) back from the 1st exaflare, just outside\n            -- the boss circle by the 3rd bait, then on round the way the exaflares spawned.\n            local start = (first - 67.5 * sign) % 360\n            local E = s.ELEMENTAL\n            return {\n                mid, s.at(start, E.OUT1), s.at(start, E.OUT2),\n                s.at(start + sign * E.TURN, E.WALL), s.at(start + 2 * sign * E.TURN, E.WALL), s.at(start + 3 * sign * E.TURN, E.WALL),\n            }, start, sign\n        end\n        local marker = (first - 45 * sign) % 360\n        return {\n            mid, s.at(marker, s.OUT), s.at(marker, 2 * s.OUT),\n            s.at(marker + sign * s.TURN, s.WALL), s.at(marker + 2 * sign * s.TURN, s.WALL), s.at(marker + 3 * sign * s.TURN, s.WALL),\n        }, marker, sign\n    end\n\n    -- Alpha Omega's hitbox edge on the bearing of the last bait.\n    function s.hitbox(lastSpot)\n        local boss\n        for _, e in pairs(TensorCore.entityList(\"contentid=12256\")) do\n            if e.hitradius and (boss == nil or e.hitradius > boss.hitradius) then boss = e end\n        end\n        local r = boss and boss.hitradius or 5\n        local cx, cz = boss and boss.pos and boss.pos.x or 100, boss and boss.pos and boss.pos.z or 100\n        local dx, dz = lastSpot.x - cx, lastSpot.z - cz\n        local len = math.sqrt(dx * dx + dz * dz)\n        if len < 0.01 then return { x = cx, z = cz } end\n        local reach = math.max(0, r - 0.5)\n        return { x = cx + dx / len * reach, z = cz + dz / len * reach }\n    end\nend\n\nlocal me = TensorCore.mGetPlayer()\nlocal u = data.topUwc\nif not values.uwcArrow or me == nil or me.pos == nil or me.hp.current <= 0 or u == nil or Now() - u.at > 30000 then\n    self.used = true\n    return\nend\n-- A new Unlimited Wave Cannon: start the log lines afresh.\nif s.seen ~= u.at then\n    s.seen, s.warned = u.at, {}\nend\nlocal second = t >= s.UWC2_FROM\nlocal spot, nextSpot\nif #u.exas < 2 then\n    spot = { x = 100, z = 100 }\nelse\n    local spots, marker, sign = s.plan(u.exas[1].bearing, u.exas[2].bearing)\n    s.warnOnce(\"plan\" .. tostring(second), string.format(\"%s: exas at %.0f then %.0f, marker %.0f, turning %s\",\n        second and \"UWC2\" or \"UWC1\", u.exas[1].bearing, u.exas[2].bearing, marker, sign > 0 and \"clockwise\" or \"counter-clockwise\"))\n    local placed = #u.baits\n    -- UWC2: the user wants the arrow gone once the 5th puddle is placed (2026-11-08).\n    if second and placed >= 5 then\n        placed = 99\n    elseif placed < 6 then\n        spot, nextSpot = spots[placed + 1], spots[placed + 2]\n        if second and placed == 4 then nextSpot = nil end\n    elseif second and t < s.DIVE then\n        spot = s.hitbox(spots[6])\n    end\n    if spot then\n        s.warnOnce(\"step\" .. placed, string.format(\"after %d puddles: spot (%.1f,%.1f)\", placed, spot.x, spot.z))\n    end\nend\nif spot == nil then\n    self.used = true\n    return\nend\nlocal y = me.pos.y\ns.drawMine:addCircle(spot.x, y, spot.z, 1.5)\nif nextSpot then s.drawNext:addCircle(nextSpot.x, y, nextSpot.z, 1.2) end\nfor _, p in ipairs((data.topUwc and data.topUwc.puddles) or {}) do\n    if Now() - p.at < 2700 then s.drawPuddle:addCircle(p.x, y, p.z, 6) end\nend\nlocal dx, dz = spot.x - me.pos.x, spot.z - me.pos.z\nlocal dist = math.sqrt(dx * dx + dz * dz)\nif dist > 0.5 then\n    -- Sized like the standard guide arrow, except it keeps pointing up close.\n    local scale = math.min(1, dist / 15)\n    local near = math.min(1, dist / 3)\n    local tipLength = math.min(math.max(2, 3 * scale), dist * 2 / 3)\n    s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spot.x, y, spot.z),\n        dist - tipLength, math.max(0.5, scale) * near, tipLength, math.max(1.5, 3 * scale) * near,\n        false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\nend\nself.used = true\n",
							name = "Draw Exaflare Arrow",
							uuid = "dde4c562-2506-6c58-a0da-a18e3d07f4d6",
							version = 2.1,
						},
					},
				},
				conditions = 
				{
				},
				eventType = 12,
				loop = true,
				mechanicTime = 1291.7,
				name = "[UWC] Arrow 2",
				timeRange = true,
				timelineIndex = 251,
				timerEndOffset = 21,
				timerStartOffset = -6,
				uuid = "4c710a99-35e2-4762-9c39-8b8c9dc2ff35",
				version = 2,
			},
		},
	},
